Object.assign(ACT,{
 ficha:t=>go('ficha',{id:t.dataset.id,tab:'dados'}),
 fCsv:()=>{const {fs}=D();csv('funcionarios.csv',[['Matrícula','Nome','CPF','Função','Admissão','Status','Telefone'],...fs.map(f=>[f.matricula,f.nome,f.cpf,funcaoNome(f.funcao_id),fD(f.data_admissao),f.status,f.telefone])])},
 fNovo:()=>openModal(`<h2>Cadastro direto de funcionário</h2><p class="muted">Use para registrar quem já trabalha na Avante. Contratações novas devem passar pela Nova admissão.</p>
  <div class="row"><div><label>Nome completo *</label><input id="nfNome"></div><div><label>CPF *</label><input id="nfCpf"></div><div><label>Matrícula *</label><input id="nfMat"></div></div>
  <div class="row"><div><label>Função *</label><select id="nfFunc">${optList(S.ref.funcoes,'','Selecione')}</select></div><div><label>Data de admissão *</label><input type="date" id="nfAdm"></div><div><label>Tipo de contrato</label><select id="nfCt">${CONTRATOS.map(c=>`<option>${c}</option>`).join('')}</select></div></div>
  ${perm('salarios','incluir')?`<div class="row"><div><label>Salário (R$) *</label><input type="number" step="0.01" id="nfSal"></div><div><label>Vale-alimentação (R$/mês)</label><input type="number" step="0.01" id="nfVa" value="300"></div></div>`:''}
  <div id="err" class="err"></div><div class="modal-actions"><button class="btn" data-act="close">Cancelar</button><button class="btn primary" data-act="fNovoOk">Salvar e abrir ficha</button></div>`),
 fNovoOk:async()=>{const nome=$('#nfNome').value.trim(),cpf=$('#nfCpf').value.trim(),mat=$('#nfMat').value.trim(),fn=$('#nfFunc').value,adm=$('#nfAdm').value;if(!nome||!cpf||!mat||!fn||!adm){$('#err').textContent='Preencha os campos com *.';return}
  const sal=$('#nfSal')?+$('#nfSal').value:0;if($('#nfSal')&&!sal){$('#err').textContent='Informe o salário.';return}
  const f=(await S.api.insert('funcionarios',[{nome,cpf,matricula:mat,funcao_id:fn,data_admissao:adm,tipo_contrato:$('#nfCt').value}]))[0];
  if($('#nfSal')){const F=S.ref.funcoes.find(x=>x.id===fn);await S.api.insert('funcionarios_remuneracao',[{funcionario_id:f.id,salario:sal,adicional_pct:F.periculosidade_pct||0,va_valor:+$('#nfVa').value||F.va_padrao||300}])}
  closeModal();toast('Funcionário cadastrado');go('ficha',{id:f.id,tab:'dados'})},
 fImport:()=>openModal(`<h2>Importar funcionários (CSV)</h2><p>Monte uma planilha com as colunas abaixo, nesta ordem, e salve como <b>CSV (separado por ponto e vírgula)</b>:</p><p class="small" style="font-family:monospace;background:var(--surface2);padding:8px;border-radius:6px">matricula;nome;cpf;funcao;data_admissao(dd/mm/aaaa);salario;telefone</p><p class="small muted">A função precisa ter o mesmo nome cadastrado em Cadastros › Funções. Linhas com matrícula já existente são ignoradas.</p><input type="file" id="impArq" accept=".csv,text/csv"><div id="err" class="err"></div><div id="impRes" class="small"></div><div class="modal-actions"><button class="btn" data-act="close">Fechar</button><button class="btn primary" data-act="fImportOk">Importar</button></div>`),
 fImportOk:async()=>{const f=$('#impArq').files[0];if(!f){$('#err').textContent='Escolha o arquivo.';return}const txt=(await f.text()).replace(/^﻿/,'');const linhas=txt.split(/\r?\n/).filter(l=>l.trim());const ex=new Set(D().fs.map(x=>x.matricula));let ok=0,err=[];
  for(const [i,l] of linhas.entries()){const c=l.split(';').map(x=>x.trim().replace(/^"|"$/g,''));if(i===0&&/matr/i.test(c[0]))continue;const[mat,nome,cpf,func,adm,sal,tel]=c;if(!mat||!nome)continue;if(ex.has(mat))continue;
   const F=S.ref.funcoes.find(x=>x.nome.toLowerCase()===(func||'').toLowerCase());const[dD,mM,aA]=(adm||'').split('/');if(!F||!aA){err.push('Linha '+(i+1)+': '+(F?'data inválida':'função "'+func+'" não cadastrada'));continue}
   try{const r=(await S.api.insert('funcionarios',[{matricula:mat,nome:nome.toUpperCase(),cpf:cpf||null,funcao_id:F.id,data_admissao:aA+'-'+mM.padStart(2,'0')+'-'+dD.padStart(2,'0'),telefone:tel||null}]))[0];
    if(sal&&perm('salarios','incluir'))await S.api.insert('funcionarios_remuneracao',[{funcionario_id:r.id,salario:+String(sal).replace(/\./g,'').replace(',','.'),adicional_pct:F.periculosidade_pct||0,va_valor:F.va_padrao||300}]);ok++;ex.add(mat)}catch(e){err.push('Linha '+(i+1)+': '+e.message)}}
  $('#impRes').innerHTML=`<p><b>${ok} funcionário(s) importado(s).</b></p>${err.length?'<p style="color:var(--bad)">'+err.slice(0,15).map(esc).join('<br>')+'</p>':''}`;await evento('Importou funcionários',ok+' registros');if(ok)reload()}});

