function calcDia(r,d){const c=carga(d);const o={carga:c,trab:0,normal:0,atraso:0,falta:0,he50:0,he100:0,erro:''};if(vazioR(r))return o;
 if(r.ocorrencia==='TRABALHADO'){const t=(hm(r.saida1)-hm(r.entrada1))+(hm(r.saida2)-hm(r.entrada2));if(isNaN(t)||t<=0){o.erro='Marcações incompletas';return o}o.trab=t;
  if(isFer(d)||d.getDay()===0)o.he100=t;else if(c===0)o.he50=t;else{const df=t-c;if(Math.abs(df)<=TOL())o.normal=c;else if(df>0){o.normal=c;o.he50=df}else{o.normal=t;o.atraso=-df}}}
 else if(r.ocorrencia==='FALTA')o.falta=c;else if(PAGO.includes(r.ocorrencia))o.normal=c;return o}
