 if(t.dataset.f==='pq'||t.dataset.f==='po'){S.f[t.dataset.f]=t.value;if(t.dataset.f==='po'&&ev.type!=='change')return true;const pos=t.selectionStart;render();const n=document.querySelector(`[data-f="${t.dataset.f}"]`);if(n&&t.dataset.f==='pq'){n.focus();n.setSelectionRange(pos,pos)}return true}
