 valida:r=>{if(!(r.litros>0))return 'Litros deve ser maior que zero.';return null},
 prev:c=>{const vid=$('#cf_veiculo_id').value;const v=vObj(vid);if(c==='veiculo_id'&&v.id){if(!$('#cf_combustivel').value)$('#cf_combustivel').value=v.combustivel||'';if(!$('#cf_obra_id').value&&v.obra_id)$('#cf_obra_id').value=v.obra_id;if(!$('#cf_funcionario_id').value&&v.condutor_id)$('#cf_funcionario_id').value=v.condutor_id}
  const km=numBR($('#cf_km').value),l=numBR($('#cf_litros').value),vt=numBR($('#cf_valor_total').value),data=$('#cf_data').value;const id=(document.querySelector('[data-act="cfSalvar"]')||{dataset:{}}).dataset.id;const out=[];const u=unid(v);
  if(l&&vt)out.push(`Preço por litro: <b>${BRL2(vt/l)}</b>`);
  const ult=vid&&data?ultLeitura(vid,data,id):null;
  if(ult&&km!=null){const dist=km-ult.km;if(dist<0)out.push(`<span style="color:var(--bad)">${u.t} menor que o último registro (${fN1(+ult.km)} em ${fD(ult.data)}). Confira o hodômetro.</span>`);else{out.push(`Desde o último abastecimento (${fD(ult.data)}): <b>${fN1(dist)} ${u.d}</b>`);
   if($('#cf_tanque_cheio').checked&&l&&dist>0){const s=consumoSeg((D().L||[]).filter(a=>a.veiculo_id===vid&&a.id!==id).concat([{id:'_n',veiculo_id:vid,data,km,litros:l,tanque_cheio:true}])).find(x=>x.id==='_n');if(s){const c=kml(s,v);out.push(`Consumo: <b>${fN1(c,2)} ${u.c}</b>${v.consumo_referencia?` (referência ${fN1(+v.consumo_referencia,1)})`:''}`);if(v.consumo_referencia&&c&&(u.c==='km/l'?c<v.consumo_referencia*0.8:c>v.consumo_referencia*1.2))out.push('<span style="color:var(--warn)">Consumo mais de 20% pior que a referência: vale conferir o lançamento.</span>')}}}}
  if(l&&v.tanque_litros&&l>v.tanque_litros*1.05)out.push(`<span style="color:var(--bad)">Litros acima da capacidade do tanque (${fN1(+v.tanque_litros)} l).</span>`);
  $('#cfPrev').innerHTML=out.join('<br>')},
 kpis:L=>{const l=L.reduce((s,a)=>s+(+a.litros),0),v=L.reduce((s,a)=>s+(+a.valor_total),0);return kc('Gasto no período',BRL(v),L.length+' abastecimento(s)')+kc('Litros',fN1(l)+' l','')+kc('Preço médio',l?BRL2(v/l)+'/l':'—','valor ÷ litros')},
 cols:[['Data',a=>fD(a.data)],['Veículo',a=>`<b>${esc(vNome(a.veiculo_id))}</b>`],['Condutor',a=>esc(condNome(a))],['Obra',a=>esc(obraNome(a.obra_id)||'—')],['Km/h',a=>fN1(+a.km),1],['Litros',a=>fN1(+a.litros,2),1],['Valor',a=>BRL2(+a.valor_total),1],['R$/l',a=>BRL2(a.valor_total/a.litros),1],['Consumo',a=>{const v=vObj(a.veiculo_id);const s=consumoSeg((D().L||[]).filter(x=>x.veiculo_id===a.veiculo_id)).find(x=>x.id===a.id);if(!s)return a.tanque_cheio?'<span class="muted">—</span>':'<span class="small muted">parcial</span>';const c=kml(s,v);if(segSuspeito(s,v))return `${fN1(c,2)} ${unid(v).c} ${pill('conferir km','bad')}`;const ruim=v.consumo_referencia&&(unid(v).c==='km/l'?c<v.consumo_referencia*0.8:c>v.consumo_referencia*1.2);return `${fN1(c,2)} ${unid(v).c}${ruim?' '+pill('fora do padrão','warn'):''}`},1]],
