  const conc=B2C.filter(n=>n.situacao==='Concluído');const ciclo=conc.map(n=>{const a=(n.dados||{}).credito,b=(n.dados||{}).obra;return a&&a.ini&&b&&b.fim?diasEntre(a.ini,b.fim):null}).filter(x=>x!=null);
  const ano=String(T0.getFullYear());const obrasAno=conc.filter(n=>String(((n.dados||{}).obra||{}).fim||'').startsWith(ano)).length;
