const DRE_LIN=[['receita','Receita bruta de obras e serviços'],['deducao','Impostos sobre o faturamento'],['custo','Custos das obras e serviços'],['despesa','Despesas operacionais (administrativas e comerciais)'],['fin_rec','Receitas financeiras'],['fin_desp','Despesas financeiras'],['outras_rec','Outras receitas'],['outras_desp','Outras despesas'],['ir_csll','IRPJ e CSLL (impostos sobre o lucro)'],['fora','Fora da DRE (transferências, amortização de empréstimos)']];
function dreLinha(c){if(!c||!c.id)return null;if(c.dre_linha)return c.dre_linha;const g=c.grupo||'';if(g==='Transferências')return 'fora';if(c.tipo==='Receita')return /obra|servi/i.test(g)?'receita':/financ/i.test(g)?'fin_rec':'outras_rec';
 if(/^(IRPJ|CSLL)$/.test(c.nome))return 'ir_csll';if(c.nome==='Impostos sobre faturamento'||/^(PIS|COFINS|ISS)$/.test(c.nome))return 'deducao';if(/Empréstimos/.test(c.nome))return 'fora';if(/Custos de obra|Frota/.test(g)||(g==='Pessoal'&&c.nome!=='Pró-labore'))return 'custo';if(/Financeiras/.test(g))return 'fin_desp';if(g==='Outras')return 'outras_desp';return 'despesa'}
const FORMAS=['Pix','Boleto','Transferência','Cartão de crédito','Cartão de débito','Dinheiro','Débito automático','Cheque'];
const TIPOS_CONTA=['Conta corrente','Poupança','Caixa (dinheiro)','Cartão de crédito','Aplicação'];
const uuidv4=()=>(crypto&&crypto.randomUUID)?crypto.randomUUID():'xxxxxxxx-xxxx-4xxx-8xxx-xxxxxxxxxxxx'.replace(/x/g,()=>(Math.random()*16|0).toString(16));
async function finBase(){const[ct,cat,fav,L,ic]=await Promise.all([S.api.select('fin_contas',{order:['nome']}),S.api.select('fin_categorias',{order:['nome']}),S.api.select('fin_favorecidos',{order:['nome']}),S.api.select('fin_lancamentos',{order:['vencimento']}),S.api.select('configuracoes',{eq:{chave:'impostos'}}).catch(()=>[])]);FN.impCfg=(ic&&ic[0]&&ic[0].valor)||{};FN.virt=new Set(ct.filter(c=>c.virtual).map(c=>c.id));L.forEach(l=>{if(FN.virt.has(l.conta_id))l._v=true});FN.ct=ct;FN.cat=cat;FN.fav=fav;FN.L=L;return {ct,cat,fav,L}}
const FN={};
const fnCat=id=>(FN.cat||[]).find(c=>c.id===id)||{};const fnFav=id=>((FN.fav||[]).find(c=>c.id===id)||{}).nome||'';const fnConta=id=>((FN.ct||[]).find(c=>c.id===id)||{}).nome||'';
const fnSt=l=>l.data_pagamento?'pago':pdk(l.vencimento)<T0?'vencido':dk(T0)===String(l.vencimento).slice(0,10)?'hoje':'aberto';
const fnStPill=l=>({pago:pill(l.tipo==='R'?'Recebido':'Pago','ok'),vencido:pill('Vencido','bad'),hoje:pill('Vence hoje','warn'),aberto:pill('A vencer','')})[fnSt(l)];
const fnVal=l=>l.data_pagamento?+(l.valor_pago??l.valor):+l.valor;
// distribuição por obra (centro de custo), respeitando o rateio
function fnObras(l){if(Array.isArray(l.rateio)&&l.rateio.length)return l.rateio.map(r=>({obra:r.obra_id,v:fnVal(l)*(+r.pct||0)/100}));return [{obra:l.obra_id||null,v:fnVal(l)}]}
function fnSaldoAte(d,ate,contaId){return (d.ct||[]).filter(c=>!c.virtual&&(!contaId||c.id===contaId)).reduce((s,c)=>{const ini=pdk(c.saldo_data);const mov=(d.L||[]).filter(l=>l.conta_id===c.id&&l.data_pagamento&&l.pagador!=='Cliente'&&pdk(l.data_pagamento)>=ini&&pdk(l.data_pagamento)<=ate).reduce((a,l)=>a+(l.tipo==='R'?1:-1)*(+(l.valor_pago??l.valor)),0);return s+(+c.saldo_inicial||0)+mov},0)}
const mesAdd=(k,n)=>{const[y,m]=k.split('-').map(Number);const d=new Date(y,m-1+n,1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')};
const addMes=(ds,n)=>{const d=pdk(ds);const t=new Date(d.getFullYear(),d.getMonth()+n,1);const last=new Date(t.getFullYear(),t.getMonth()+1,0).getDate();return dk(new Date(t.getFullYear(),t.getMonth(),Math.min(d.getDate(),last)))};

