  let retencoes=null,liq=bruto;if($('#fnRetOn').checked){retencoes={};document.querySelectorAll('[data-ret]').forEach(x=>{const v=numBR(x.value);if(v)retencoes[x.dataset.ret]=v});liq=Math.round((bruto-fnRetTot())*100)/100;if(liq<0){$('#err').textContent='As retenções passam do valor.';return}}
