Object.assign(ACT,{fnImport:t=>{S._fnImpTp=t.dataset.tp;openModal(`<h2>Importar ${t.dataset.tp==='P'?'contas a pagar':'contas a receber'}</h2><p class="small muted">CSV separado por ponto e vírgula, com cabeçalho. Colunas aceitas (a ordem não importa):</p>
 <pre class="small" style="background:var(--surface2);padding:8px;border-radius:8px;white-space:pre-wrap">vencimento;valor;favorecido;descricao;categoria;documento;centro_custo;conta;data_pagamento;valor_pago</pre>
 <p class="small muted">Favorecidos e categorias que não existirem são criados. O centro de custo é ligado à obra cujo nome aparecer no texto (ex.: "166 - RODRIGO AYRES" → RODRIGO). Datas em dd/mm/aaaa; valores como 1.234,56.</p>
 <input type="file" id="fnImpF" accept=".csv,.txt"><div id="fnImpPrev" class="small mt"></div><div id="err" class="err"></div>
 <div class="modal-actions"><button class="btn" data-act="close">Cancelar</button><button class="btn primary" data-act="fnImpOk" disabled>Importar</button></div>`,true)},
 fnImpOk:async()=>{const R=S._fnImp;if(!R)return;const tp=S._fnImpTp;const nrm=s=>String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().trim();
  const favMap={};(FN.fav||[]).forEach(f=>favMap[nrm(f.nome)]=f.id);const catMap={};(FN.cat||[]).filter(c=>c.tipo===(tp==='P'?'Despesa':'Receita')).forEach(c=>catMap[nrm(c.nome)]=c.id);
  for(const n of [...new Set(R.map(r=>r.fav).filter(x=>x&&!favMap[nrm(x)]))]){const f=(await S.api.insert('fin_favorecidos',[{nome:n,tipo:tp==='P'?'Fornecedor':'Cliente'}]))[0];favMap[nrm(n)]=f.id}
  for(const n of [...new Set(R.map(r=>r.cat).filter(x=>x&&!catMap[nrm(x)]))]){const c=(await S.api.insert('fin_categorias',[{nome:n,tipo:tp==='P'?'Despesa':'Receita',grupo:'Importadas'}]))[0];catMap[nrm(n)]=c.id}
  const rows=R.map(r=>({tipo:tp,descricao:r.desc,favorecido_id:r.fav?favMap[nrm(r.fav)]:null,categoria_id:r.cat?catMap[nrm(r.cat)]:null,conta_id:r.conta,obra_id:r.obra,vencimento:r.venc,valor:r.valor,documento:r.doc,data_pagamento:r.pg,valor_pago:r.pg?(r.vp??r.valor):null}));
  for(let i=0;i<rows.length;i+=200)await S.api.insert('fin_lancamentos',rows.slice(i,i+200));await evento('Importou lançamentos financeiros',rows.length+' linhas');closeModal();toast(rows.length+' lançamento(s) importado(s).');reload()}});
FIELD.push(async ev=>{const t=ev.target;if(t.id!=='fnImpF'||ev.type!=='change')return false;const f=t.files[0];if(!f)return true;let tx=await f.text();if(tx.charCodeAt(0)===0xFEFF)tx=tx.slice(1);const nrm=s=>String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().trim();
 const ls=tx.split(/\r?\n/).filter(l=>l.trim());const sep=ls[0].includes(';')?';':',';const H=ls[0].split(sep).map(h=>nrm(h).replace(/\s+/g,'_'));const ix=k=>H.indexOf(k);
 const dt=s=>{s=String(s||'').trim();let m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);if(m)return `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);return m?m[0]:null};
 const obras=S.ref.obras.map(o=>({id:o.id,n:nrm(o.nome)})).sort((a,b)=>b.n.length-a.n.length);const ok=[],er=[];let semObra=0;
 ls.slice(1).forEach((l,i)=>{const c=l.split(sep).map(x=>x.trim().replace(/^"|"$/g,''));const g=k=>ix(k)>=0?c[ix(k)]:'';const venc=dt(g('vencimento')),valor=numBR(g('valor'));if(!venc||valor==null){er.push(`Linha ${i+2}: vencimento ou valor inválido`);return}
  const cc=nrm(g('centro_custo'));const ob=cc?obras.find(o=>cc.includes(o.n)):null;if(cc&&!ob)semObra++;const cta=g('conta')?(FN.ct||[]).find(x=>nrm(x.nome)===nrm(g('conta'))):null;
  ok.push({venc,valor,fav:g('favorecido')||null,desc:g('descricao')||g('favorecido')||'Importado',cat:g('categoria')||null,doc:g('documento')||null,obra:ob?ob.id:null,conta:cta?cta.id:null,pg:dt(g('data_pagamento')),vp:numBR(g('valor_pago'))})});
 S._fnImp=ok;$('#fnImpPrev').innerHTML=`<b>${ok.length}</b> linha(s) prontas.${semObra?` ${semObra} com centro de custo que não corresponde a nenhuma obra cadastrada (ficam sem obra).`:''}${er.length?`<br><span style="color:var(--bad)">${er.length} com problema:</span><br>${er.slice(0,6).map(esc).join('<br>')}`:''}`;document.querySelector('[data-act="fnImpOk"]').disabled=!ok.length;return true});

