// ================================================================ FINANCEIRO · IMPORTAR NOTA FISCAL EM PDF (NFS-e / DANFE)
// leitura do texto do PDF com a biblioteca pdf.js (arquivos em /lib, servidos junto com o portal)
let _pdfjs=null;
async function pdfTexto(file){if(!_pdfjs){_pdfjs=await import(new URL('lib/pdf.min.mjs',location.href).href);_pdfjs.GlobalWorkerOptions.workerSrc=new URL('lib/pdf.worker.min.mjs',location.href).href}
 const doc=await _pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;let out=[];
 for(let p=1;p<=Math.min(doc.numPages,6);p++){const pg=await doc.getPage(p);const tc=await pg.getTextContent();const L={};tc.items.forEach(it=>{if(!it.str||!it.str.trim())return;const y=Math.round(it.transform[5]/3)*3;(L[y]=L[y]||[]).push({x:it.transform[4],s:it.str})});
  Object.keys(L).map(Number).sort((a,b)=>b-a).forEach(y=>out.push(L[y].sort((a,b)=>a.x-b.x).map(i=>i.s).join(' ').replace(/\s+/g,' ').trim()))}
 return out.join('\n')}
const RX_MOEDA=/(?:R\$\s*)?(\d{1,3}(?:\.\d{3})*,\d{2}|\d+,\d{2})/;
function nfMoeda(t,labels){for(const lb of labels){const re=new RegExp(lb+'[^\\n\\d]{0,40}?'+RX_MOEDA.source,'i');const m=t.match(re);if(m)return numBR(m[1]);const re2=new RegExp(lb+'[^\\n]*\\n[^\\n]*?'+RX_MOEDA.source,'i');const m2=t.match(re2);if(m2)return numBR(m2[1])}return null}
const fmtDocNum=d=>d.length===14?d.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/,'$1.$2.$3/$4-$5'):d.length===11?d.replace(/^(\d{3})(\d{3})(\d{3})(\d{2})$/,'$1.$2.$3-$4'):d;
function nfParse(t){const T=t.replace(/ /g,' ');const up=T.toUpperCase();const dataBR=s=>{const m=String(s||'').match(/(\d{2})\/(\d{2})\/(\d{4})/);return m?`${m[3]}-${m[2]}-${m[1]}`:null};
 const tipoNF=/DANFE|DOCUMENTO AUXILIAR DA NOTA FISCAL ELETR/i.test(T)?'NF-e':'NFS-e';
 let numero=null;for(const re of [/N[ÚU]MERO\s+(?:DA\s+)?NFS-?E\s*[:\-]?\s*\n?\s*0*(\d{1,12})/i,/NFS-?E\s*N[º°o.]*\s*[:\-]?\s*0*(\d{1,12})/i,/N[º°o]\s*(?:DA\s+)?NOTA\s*[:\-]?\s*0*(\d{1,12})/i,/N[º°o]\.?\s*0*(\d{3}\.\d{3}\.\d{3}|\d{1,9})\s*\n?\s*S[ÉE]RIE/i,/NOTA\s+FISCAL[^\n]{0,40}?N[º°o]?\s*[:\-]?\s*0*(\d{1,12})/i,/N[ÚU]MERO\s*[:\-]?\s*0*(\d{1,12})/i]){const m=T.match(re);if(m){numero=m[1].replace(/\D/g,'').replace(/^0+/,'');break}}
 const em=(T.match(/EMISS[ÃA]O[^\n\d]{0,30}(\d{2}\/\d{2}\/\d{4})/i)||T.match(/(\d{2}\/\d{2}\/\d{4})/)||[])[1];
 const venc=(T.match(/VENCIMENTO[^\n\d]{0,30}(\d{2}\/\d{2}\/\d{4})/i)||[])[1];
 const docs=[...T.matchAll(/\b(\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2}|\d{3}\.\d{3}\.\d{3}-\d{2})\b/g)].map(m=>m[1].replace(/\D/g,''));const nossa=String(empCnpj()).replace(/\D/g,'');
 // bloco do tomador (NFS-e) ou destinatário (DANFE)
 const iT=up.search(/TOMADOR|DESTINAT[ÁA]RIO/);const iT2=iT>=0?(up.indexOf('\n',iT)>0?up.indexOf('\n',iT):iT+10):-1;const fimT=iT2>=0?up.slice(iT2).search(/DISCRIMINA|INTERMEDI|DADOS DOS PRODUTOS|C[ÁA]LCULO DO IMPOSTO|FATURA|\nSERVI[ÇC]OS?\b/):-1;const blocoT=iT>=0?T.slice(iT,fimT>0?iT2+fimT:iT+700):'';
 const iP=up.search(/PRESTADOR|EMITENTE|IDENTIFICA[ÇC][ÃA]O DO EMITENTE/);const blocoP=iP>=0?T.slice(iP,iP+600):'';
 const docDe=b=>{const m=[...b.matchAll(/(\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2}|\d{3}\.\d{3}\.\d{3}-\d{2})/g)].map(x=>x[1].replace(/\D/g,''));return m[0]||null};
 const nomeDe=b=>{const m=b.match(/(?:RAZ[ÃA]O\s+SOCIAL|NOME\s*\/?\s*RAZ[ÃA]O\s+SOCIAL|NOME)\s*[:\-]?\s*([^\n]{3,90})/i);if(!m)return null;return m[1].replace(/\s*(CPF|CNPJ|INSCRI|E-?MAIL|ENDERE|TELEFONE|MUNIC)[\s\S]*$/i,'').replace(/[:\-–]+\s*$/,'').trim()||null};
 const tomDoc=docDe(blocoT),preDoc=docDe(blocoP);
 const bruto=nfMoeda(T,['VALOR\\s+(?:TOTAL\\s+)?(?:DOS?\\s+)?SERVI[ÇC]OS?','VALOR\\s+TOTAL\\s+DA\\s+NOTA','VALOR\\s+DA\\s+NOTA','VALOR\\s+BRUTO','VALOR\\s+TOTAL']);
 const liquido=nfMoeda(T,['VALOR\\s+L[ÍI]QUIDO(?:\\s+DA\\s+NFS-?E)?']);
 const issRet=/ISS\s*RETIDO\s*[:\-]?\s*(SIM|S\b|\(X\)\s*SIM)/i.test(T)||/RETEN[ÇC][ÃA]O\s+DO\s+ISS\s*[:\-]?\s*SIM/i.test(T);
 const ret={};const add=(k,lbs)=>{const v=nfMoeda(T,lbs);if(v)ret[k]=v};
 add('inss',['INSS\\s*(?:RETIDO)?\\s*(?:\\(R\\$\\))?']);add('irrf',['IR(?:RF)?\\s*(?:RETIDO)?\\s*(?:\\(R\\$\\))?']);['PIS','COFINS','CSLL'].forEach(k=>add(k.toLowerCase(),[k+'\\s*(?:RETIDO)?\\s*(?:\\(R\\$\\))?']));
 if(issRet){const v=nfMoeda(T,['VALOR\\s+DO\\s+ISS\\s+RETIDO','ISS\\s+RETIDO\\s*\\(R\\$\\)','VALOR\\s+(?:DO\\s+)?ISS']);if(v)ret.iss=v}
 let somaRet=Object.values(ret).reduce((a,b)=>a+b,0);
 // se o PDF trouxer o líquido, ele manda: ajusta as retenções para fechar a conta
 if(bruto&&liquido&&Math.abs(bruto-somaRet-liquido)>0.02){if(liquido<bruto){const dif=Math.round((bruto-liquido)*100)/100;Object.keys(ret).forEach(k=>delete ret[k]);ret.total=dif;somaRet=dif}else{Object.keys(ret).forEach(k=>delete ret[k]);somaRet=0}}
 if(bruto&&liquido==null&&somaRet>=bruto){Object.keys(ret).forEach(k=>delete ret[k]);somaRet=0}
 const disc=(T.match(/DISCRIMINA[ÇC][ÃA]O\s+DOS?\s+SERVI[ÇC]OS?\s*[:\-]?\s*\n?([\s\S]{3,400}?)(?:\n\s*(?:VALOR|C[ÓO]DIGO|ATIVIDADE|OUTRAS|DEDU)|$)/i)||T.match(/DESCRI[ÇC][ÃA]O\s+DO\s+PRODUTO[^\n]*\n([^\n]{3,200})/i)||[])[1];
 return {tipoNF,numero,emissao:dataBR(em),vencimento:dataBR(venc),tomador:{doc:tomDoc,nome:nomeDe(blocoT)},prestador:{doc:preDoc,nome:nomeDe(blocoP)},bruto,liquido:liquido??(bruto!=null?Math.round((bruto-somaRet)*100)/100:null),ret,disc:disc?disc.replace(/\s+/g,' ').trim().slice(0,160):null,docs:[...new Set(docs)].filter(d=>d!==nossa),textoCurto:T.length<60}}
// a outra parte da nota (quem não é a Avante)
function nfParte(n,tp){const nossa=String(empCnpj()).replace(/\D/g,'');const a=tp==='R'?n.tomador:n.prestador,b=tp==='R'?n.prestador:n.tomador;if(a.doc&&a.doc!==nossa)return a;if(b.doc&&b.doc!==nossa&&b.doc!==a.doc&&(!a.doc||a.doc===nossa))return b;return {doc:a.doc&&a.doc!==nossa?a.doc:(n.docs[0]||null),nome:a.nome}}
async function nfFavorecido(parte,tp){const doc=String(parte.doc||'').replace(/\D/g,'');let f=doc?(FN.fav||[]).find(x=>String(x.cpf_cnpj||'').replace(/\D/g,'')===doc):null;if(f)return f;
 if(!parte.nome&&!doc)return null;let cli=null;if(doc&&perm('comercial','ver')){try{cli=(await S.api.select('clientes')).find(c=>String(c.cpf_cnpj||'').replace(/\D/g,'')===doc)}catch(e){}}
 f=(await S.api.insert('fin_favorecidos',[{nome:parte.nome||(cli&&cli.nome)||('CNPJ '+fmtDocNum(doc)),cpf_cnpj:doc?fmtDocNum(doc):null,tipo:tp==='R'?'Cliente':'Fornecedor',cliente_id:cli?cli.id:null}]))[0];FN.fav.push(f);return f}
// usado no "Buscar dados" do lançamento (uma nota)
async function nfPdfNoForm(file){toast('Lendo o PDF…');let t;try{t=await pdfTexto(file)}catch(e){toast('Não foi possível ler o PDF: '+e.message,true);return}const n=nfParse(t);if(n.textoCurto){toast('Este PDF não tem texto (é uma imagem digitalizada). Preencha à mão ou use o XML.',true);return}
 const tp=($('[data-act="fnSalvar"]')||{dataset:{}}).dataset.tp;const parte=nfParte(n,tp);const f=await nfFavorecido(parte,tp);if(f){if(!$(`#fnFav option[value="${f.id}"]`))$('#fnFav').insertAdjacentHTML('beforeend',`<option value="${f.id}">${esc(f.nome)}</option>`);$('#fnFav').value=f.id}
 if(n.numero)$('#fnDoc').value='NF '+n.numero;if(n.bruto!=null)$('#fnVal').value=String(n.bruto).replace('.',',');if(n.emissao)$('#fnComp').value=n.emissao;if(n.vencimento)$('#fnVenc').value=n.vencimento;
 if(!$('#fnDesc').value)$('#fnDesc').value=(n.tipoNF+' '+(n.numero||'')+(n.disc?' - '+n.disc:'')).slice(0,140);
 if(Object.keys(n.ret).length)fnRetSet(n.ret);
 fnPrev();toast(`${n.tipoNF} ${n.numero||''} lida. Confira os campos antes de confirmar.`)}

// ---------- importação em lote (Contas a receber › Importar NF em PDF)
Object.assign(ACT,{nfImport:t=>{S._nfTp=t.dataset.tp||'R';S._nfL=[];openModal(`<h2>Importar notas fiscais em PDF</h2><p class="small muted">Selecione um ou vários PDFs de NFS-e (ou DANFE). O portal lê cliente, CNPJ, número, emissão, valor e retenções e cria um título a receber para cada nota, com o PDF anexado. Confira antes de criar.</p>
 <label class="drop" id="nfDrop"><input type="file" id="nfF" accept=".pdf" multiple style="display:none"><span class="drop-i">+</span><span><span style="color:var(--ok);font-weight:600">Clique para selecionar os PDFs ou arraste e solte aqui.</span><br><span class="small muted">PDF gerado pela prefeitura ou pelo sistema emissor (com texto). PDF escaneado não é lido.</span></span></label>
 <div id="nfRev" class="mt"></div><div id="err" class="err"></div><div class="modal-actions"><button class="btn" data-act="close">Cancelar</button><button class="btn primary" data-act="nfCriar" id="nfOk" disabled>Criar títulos</button></div>`,true);
 const dz=$('#nfDrop');['dragover','dragenter'].forEach(e=>dz.addEventListener(e,ev=>{ev.preventDefault();dz.classList.add('on')}));['dragleave','drop'].forEach(e=>dz.addEventListener(e,ev=>{ev.preventDefault();dz.classList.remove('on')}));dz.addEventListener('drop',ev=>nfArquivos([...ev.dataTransfer.files]))},
 nfCriar:async()=>{const d=D();const L=S._nfL.filter(x=>x.ok&&document.querySelector(`[data-nfi="${x.i}"]`).checked);if(!L.length){$('#err').textContent='Nenhuma nota selecionada.';return}const tp=S._nfTp;const conta=$('#nfConta').value||null;const cat=$('#nfCat').value||null;if(!conta||!cat){$('#err').textContent='Escolha a conta e a categoria.';return}
  const criados=[];for(const x of L){const g=k=>document.querySelector(`[data-nf="${x.i}|${k}"]`).value;const bruto=numBR(g('bruto'));const retTot=numBR(g('ret'))||0;const liq=Math.round((bruto-retTot)*100)/100;
   const retencoes=retTot?(Math.abs(retTot-Object.values(x.n.ret).reduce((a,b)=>a+b,0))<0.01&&Object.keys(x.n.ret).length?x.n.ret:{total:retTot}):null;
   const f=await nfFavorecido({doc:x.parte.doc,nome:g('nome')||x.parte.nome},tp);
   const row={tipo:tp,descricao:g('desc')||('NFS-e '+(g('num')||'')),favorecido_id:f?f.id:null,categoria_id:cat,conta_id:conta,obra_id:g('obra')||null,documento:g('num')?'NF '+g('num'):null,competencia:g('emi')||g('venc'),vencimento:g('venc'),valor:liq,valor_bruto:retencoes?bruto:null,retencoes,pagador:'Empresa'};
   const l=(await S.api.insert('fin_lancamentos',[row]))[0];const path=`financeiro/${l.id}_${Date.now()}.pdf`;await S.api.upload(path,x.file);await S.api.update('fin_lancamentos',{id:l.id},{arquivo_path:path,arquivo_nome:x.file.name});criados.push(l)}
  await evento('Importou notas fiscais em PDF',criados.length+' títulos');closeModal();S.params.fm=String(criados[0].vencimento).slice(0,7);await reload();
  openModal(`<h2>${criados.length} título(s) a ${tp==='R'?'receber':'pagar'} criado(s)</h2><div class="card" style="font-family:ui-monospace,Consolas,monospace">${criados.map(r=>esc(refComprovante(r))+' · '+BRL2(+r.valor)+' · vence '+fD(r.vencimento)).join('<br>')}</div><div class="modal-actions"><button class="btn primary" data-act="close">OK</button></div>`)}});
FIELD.push(async ev=>{const t=ev.target;if(t.id==='nfF'&&ev.type==='change'){nfArquivos([...t.files]);return true}if(t.dataset&&t.dataset.nf&&(ev.type==='input'||ev.type==='change')){const[i]=t.dataset.nf.split('|');nfLiq(+i);return true}return false});
async function nfArquivos(files){files=files.filter(f=>/\.pdf$/i.test(f.name));if(!files.length)return;$('#nfRev').innerHTML='<div class="loading"><span class="spin"></span>Lendo as notas…</div>';const d=D();const tp=S._nfTp;
 const nrm=s=>String(s||'').replace(/\D/g,'').replace(/^0+/,'');const base=S._nfL.length;const prazo=30;
 for(let k=0;k<files.length;k++){const file=files[k];const x={i:base+k,file,ok:false};try{const t=await pdfTexto(file);const n=nfParse(t);x.n=n;x.parte=nfParte(n,tp);
   if(n.textoCurto)x.erro='PDF sem texto (digitalizado)';else if(n.bruto==null)x.erro='Não encontrei o valor da nota';else x.ok=true;
   const dupl=n.numero&&(d.L||[]).find(l=>l.tipo===tp&&nrm(l.documento)===nrm(n.numero)&&(!x.parte.doc||String((FN.fav.find(f=>f.id===l.favorecido_id)||{}).cpf_cnpj||'').replace(/\D/g,'')===x.parte.doc));if(dupl)x.dup=dupl;
   const fav=x.parte.doc?(FN.fav||[]).find(f=>String(f.cpf_cnpj||'').replace(/\D/g,'')===x.parte.doc):null;x.favNome=fav?fav.nome:x.parte.nome;
   x.venc=n.vencimento||(n.emissao?dk(addD(pdk(n.emissao),prazo)):dk(addD(T0,prazo)));
   const ultimaObra=fav?((d.L||[]).filter(l=>l.favorecido_id===fav.id&&l.obra_id).sort((a,b)=>String(b.vencimento).localeCompare(String(a.vencimento)))[0]||{}).obra_id:null;x.obra=ultimaObra||'';
  }catch(e){x.erro='Falha ao ler: '+e.message}S._nfL.push(x)}
 const cats=(d.cat||[]).filter(c=>c.tipo===(tp==='R'?'Receita':'Despesa')&&c.ativa!==false);const catPad=(cats.find(c=>/medi[çc]/i.test(c.nome))||cats.find(c=>/servi/i.test(c.nome))||cats[0]||{}).id;
 $('#nfRev').innerHTML=`<div class="grid" style="grid-template-columns:1fr 1fr;gap:0 12px"><div><label>Conta de recebimento</label><select id="nfConta"><option value=""></option>${(d.ct||[]).filter(c=>c.ativa!==false).map(c=>`<option value="${c.id}" ${(d.ct||[]).filter(z=>z.ativa!==false).length===1?'selected':''}>${esc(c.nome)}</option>`).join('')}</select></div><div><label>Categoria</label><select id="nfCat">${cats.map(c=>`<option value="${c.id}" ${c.id===catPad?'selected':''}>${esc(c.nome)}</option>`).join('')}</select></div></div>
 <div class="tablewrap mt"><table class="nf-rev"><thead><tr><th></th><th>Arquivo / cliente</th><th>Nº</th><th>Emissão</th><th>Vencimento</th><th>Valor bruto</th><th>Retenções</th><th>Líquido</th><th>Obra</th></tr></thead><tbody>${S._nfL.map(x=>!x.ok?`<tr><td></td><td colspan="8" class="small"><b>${esc(x.file.name)}</b> · <span style="color:var(--bad)">${esc(x.erro)}</span>. Lance pelo botão "+ Nova conta".</td></tr>`:
  `<tr><td><input type="checkbox" data-nfi="${x.i}" ${x.dup?'':'checked'} style="width:auto"></td><td class="small"><span class="muted">${esc(x.file.name)}</span><input data-nf="${x.i}|nome" value="${esc(x.favNome||'')}" placeholder="Nome do cliente"><span class="muted">${x.parte.doc?fmtDocNum(x.parte.doc):'CNPJ não encontrado'}</span>${x.dup?`<div style="color:var(--warn)">Já existe: ${tituloTxt(x.dup.titulo)} (${esc(x.dup.documento||'')})</div>`:''}<input type="hidden" data-nf="${x.i}|desc" value="${esc(((x.n.tipoNF+' '+(x.n.numero||''))+(x.n.disc?' - '+x.n.disc:'')).slice(0,140))}"></td>
  <td><input data-nf="${x.i}|num" value="${esc(x.n.numero||'')}" style="width:80px"></td><td><input type="date" data-nf="${x.i}|emi" value="${x.n.emissao||''}"></td><td><input type="date" data-nf="${x.i}|venc" value="${x.venc}"></td>
  <td><input data-nf="${x.i}|bruto" inputmode="decimal" value="${String(x.n.bruto).replace('.',',')}" style="width:100px"></td><td><input data-nf="${x.i}|ret" inputmode="decimal" value="${(()=>{const s=Object.values(x.n.ret).reduce((a,b)=>a+b,0);return s?String(Math.round(s*100)/100).replace('.',','):''})()}" style="width:90px" title="${esc(Object.entries(x.n.ret).map(([k,v])=>k.toUpperCase()+' '+BRL2(v)).join(' · '))}"></td><td class="nf-liq" id="nfLiq${x.i}"></td>
  <td><select data-nf="${x.i}|obra" style="min-width:130px"><option value="">— Sem obra</option>${obrasUser().map(o=>`<option value="${o.id}" ${o.id===x.obra?'selected':''}>${esc(o.nome)}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>
 <p class="small muted">Sem vencimento na nota, o portal usa a emissão + ${prazo} dias. Notas marcadas como "Já existe" ficam desmarcadas para não duplicar.</p>`;
 S._nfL.forEach(x=>{if(x.ok)nfLiq(x.i)});$('#nfOk').disabled=!S._nfL.some(x=>x.ok)}
function nfLiq(i){const g=k=>(document.querySelector(`[data-nf="${i}|${k}"]`)||{}).value;const b=numBR(g('bruto'))||0,r=numBR(g('ret'))||0;const el=$('#nfLiq'+i);if(el)el.innerHTML=`<b>${BRL2(b-r)}</b>`}
// ================================================================ FINANCEIRO · FILTRO DE PERÍODO (dia, mês, ano, personalizado) e FLUXO DE CAIXA
function finPer(){if(S.params.fm){S.fper={modo:'mes',ref:S.params.fm+'-01'};delete S.params.fm}const f=S.fper||(S.fper={modo:'mes',ref:dk(T0)});const r=pdk(f.ref||dk(T0));const y=r.getFullYear(),m=r.getMonth();
 if(f.modo==='dia')return {modo:'dia',ini:r,fim:r,lbl:fD(r)+' · '+DOW[r.getDay()],key:dk(r)};
 if(f.modo==='ano')return {modo:'ano',ini:new Date(y,0,1),fim:new Date(y,11,31),lbl:'Ano de '+y,key:String(y)};
 if(f.modo==='per'){let a=pdk(f.ini||dk(T0)),b=pdk(f.fim||dk(T0));if(b<a)[a,b]=[b,a];return {modo:'per',ini:a,fim:b,lbl:fD(a)+' a '+fD(b),key:dk(a)+'_'+dk(b)}}
 const k=y+'-'+String(m+1).padStart(2,'0');return {modo:'mes',ini:new Date(y,m,1),fim:new Date(y,m+1,0),lbl:mesLbl(k),key:k}}
function finPerHTML(){const P=finPer();const md=[['dia','Dia'],['mes','Mês'],['ano','Ano'],['per','Período']];
 return `<div class="fp"><div class="fp-m">${md.map(([v,l])=>`<button class="${P.modo===v?'on':''}" data-act="fpModo" data-m="${v}">${l}</button>`).join('')}</div>
 ${P.modo==='per'?`<div class="fp-r"><input type="date" data-fp="ini" value="${dk(P.ini)}"><span>até</span><input type="date" data-fp="fim" value="${dk(P.fim)}"></div>`
  :`<div class="fn-mes"><button class="btn sm" data-act="fpNav" data-n="-1" aria-label="Anterior">‹</button>${P.modo==='dia'?`<input type="date" data-fp="ref" value="${dk(P.ini)}" class="fp-dia">`:`<span>${esc(P.lbl)}</span>`}<button class="btn sm" data-act="fpNav" data-n="1" aria-label="Próximo">›</button></div>`}
 <button class="btn sm" data-act="fpHoje" title="Voltar para o período atual">Hoje</button></div>`}
Object.assign(ACT,{fpModo:t=>{const P=finPer();const m=t.dataset.m;S.fper=m==='per'?{modo:'per',ini:dk(P.ini),fim:dk(P.fim)}:{modo:m,ref:dk(P.modo==='per'?P.ini:(P.ini<=T0&&T0<=P.fim?T0:P.ini))};render()},
 fpNav:t=>{const P=finPer();const n=+t.dataset.n;const r=pdk(S.fper.ref||dk(T0));let x;if(P.modo==='dia')x=addD(r,n);else if(P.modo==='ano')x=new Date(r.getFullYear()+n,0,1);else x=new Date(r.getFullYear(),r.getMonth()+n,1);S.fper={modo:P.modo,ref:dk(x)};render()},
 fpHoje:()=>{S.fper={modo:(S.fper||{}).modo==='per'?'mes':((S.fper||{}).modo||'mes'),ref:dk(T0)};render()}});
FIELD.push(ev=>{const t=ev.target;if(!t.dataset||!t.dataset.fp)return false;if(ev.type!=='change'||!t.value)return true;const k=t.dataset.fp;if(k==='ref')S.fper={modo:'dia',ref:t.value};else{S.fper=Object.assign({modo:'per'},S.fper,{[k]:t.value})}render();return true});

// ---------- fluxo de caixa
const brlC=v=>{const a=Math.abs(v),s=v<0?'-':'';return a>=1e6?s+'R$ '+fN1(a/1e6,1)+' mi':a>=1e3?s+'R$ '+fN1(a/1e3,a>=1e5?0:1)+' mil':s+'R$ '+fN1(a,0)};
function fluxoDados(d,P){const ate=addD(P.ini,-1);const ok=l=>!isTransf(l)&&l.pagador!=='Cliente'&&!l._v;const saldoIni=fnSaldoAte(d,ate);
 const nd=Math.round((P.fim-P.ini)/864e5)+1;const gran=nd<=62?'dia':'mes';const B=[];
 if(gran==='dia')for(let x=new Date(P.ini);x<=P.fim;x=addD(x,1))B.push({ini:new Date(x),fim:new Date(x),lbl:fD(x).slice(0,5),full:fD(x)+' · '+DOW[x.getDay()].slice(0,3)});
 else for(let x=new Date(P.ini.getFullYear(),P.ini.getMonth(),1);x<=P.fim;x=new Date(x.getFullYear(),x.getMonth()+1,1)){const a=x<P.ini?P.ini:new Date(x),b0=new Date(x.getFullYear(),x.getMonth()+1,0),b=b0>P.fim?P.fim:b0;B.push({ini:a,fim:b,lbl:MESES[x.getMonth()]+'/'+String(x.getFullYear()).slice(2),full:mesLbl(dk(x).slice(0,7))})}
 const quando=l=>l.data_pagamento?pdk(l.data_pagamento):(pdk(l.vencimento)>=T0?pdk(l.vencimento):null);
 let ac=saldoIni;B.forEach(b=>{b.L=(d.L||[]).filter(l=>ok(l)&&(l.data_pagamento?(l.conta_id||true):true)).filter(l=>{const q=quando(l);return q&&q>=b.ini&&q<=b.fim});
  b.e=b.L.filter(l=>l.tipo==='R').reduce((s,l)=>s+fnVal(l),0);b.s=b.L.filter(l=>l.tipo==='P').reduce((s,l)=>s+fnVal(l),0);ac+=b.e-b.s;b.ac=ac;b.prev=b.fim>=T0&&!(b.ini<=T0&&b.fim>=T0&&gran==='dia'&&dk(b.ini)===dk(T0));b.hoje=b.ini<=T0&&T0<=b.fim});
 const atr=(d.L||[]).filter(l=>ok(l)&&!l.data_pagamento&&pdk(l.vencimento)<T0&&pdk(l.vencimento)<=P.fim);
 return {saldoIni,B,gran,atr,ent:B.reduce((s,b)=>s+b.e,0),sai:B.reduce((s,b)=>s+b.s,0)}}
function fluxoChart(F){const B=F.B;if(!B.length)return '';const W=Math.round(Math.max(560,Math.min(1500,(window.innerWidth||1200)-170))),H=300,pl=78,pr=14,pt=14,pb=34;const iw=W-pl-pr,ih=H-pt-pb;
 let mx=Math.max(0,F.saldoIni,...B.map(b=>Math.max(b.e,b.ac))),mn=Math.min(0,F.saldoIni,...B.map(b=>Math.min(-b.s,b.ac)));if(mx===mn)mx=mn+1;const pad=(mx-mn)*0.06;mx+=pad;if(mn<0)mn-=pad;
 const Y=v=>pt+ih*(mx-v)/(mx-mn);const bw=iw/B.length;const X=i=>pl+bw*i+bw/2;const bar=Math.max(2,Math.min(26,bw*0.36));
 const ticks=[];const step=(()=>{const r=(mx-mn)/6;const p=Math.pow(10,Math.floor(Math.log10(r)));return [1,2,2.5,5,10].map(k=>k*p).find(k=>k>=r)||r})();for(let v=Math.ceil(mn/step)*step;v<=mx;v+=step)ticks.push(v);
 const every=Math.ceil(B.length/Math.max(6,Math.floor(iw/70)));const iH=B.findIndex(b=>b.prev);
 const pts=B.map((b,i)=>`${X(i).toFixed(1)},${Y(b.ac).toFixed(1)}`);const real=iH<0?pts:pts.slice(0,Math.max(1,iH));const prev=iH<0?[]:pts.slice(Math.max(0,iH-1));
 return `<div class="fx-leg"><span><i style="background:var(--fx-e)"></i>Entradas</span><span><i style="background:var(--fx-s)"></i>Saídas</span><span><i class="ln"></i>Saldo acumulado</span>${prev.length?'<span><i class="ln dash"></i>Saldo previsto</span>':''}</div>
 <div class="fx-wrap"><svg class="fx" viewBox="0 0 ${W} ${H}" style="min-width:${W>700?0:W}px" role="img" aria-label="Gráfico do fluxo de caixa">
 ${ticks.map(v=>`<line x1="${pl}" x2="${W-pr}" y1="${Y(v).toFixed(1)}" y2="${Y(v).toFixed(1)}" class="${v===0?'z':'g'}"/><text x="${pl-8}" y="${(Y(v)+4).toFixed(1)}" text-anchor="end" class="t">${brlC(v)}</text>`).join('')}
 ${B.map((b,i)=>`<g class="fx-b"><rect x="${(X(i)-bw/2).toFixed(1)}" y="${pt}" width="${bw.toFixed(1)}" height="${ih}" class="hit"/>${b.e?`<rect x="${(X(i)-bar-1).toFixed(1)}" y="${Y(b.e).toFixed(1)}" width="${bar.toFixed(1)}" height="${Math.max(1,Y(0)-Y(b.e)).toFixed(1)}" rx="3" class="e${b.prev?' pv':''}"/>`:''}${b.s?`<rect x="${(X(i)+1).toFixed(1)}" y="${Y(0).toFixed(1)}" width="${bar.toFixed(1)}" height="${Math.max(1,Y(-b.s)-Y(0)).toFixed(1)}" rx="3" class="s${b.prev?' pv':''}"/>`:''}<title>${b.full}${b.prev?' (previsto)':''}&#10;Entradas: ${BRL2(b.e)}&#10;Saídas: ${BRL2(b.s)}&#10;Saldo: ${BRL2(b.ac)}</title></g>${i%every===0||(i===B.length-1&&(B.length-1)%every>=every/2)?`<text x="${X(i).toFixed(1)}" y="${H-12}" text-anchor="middle" class="t${b.hoje?' hj':''}">${b.lbl}</text>`:''}`).join('')}
 ${iH>0?`<line x1="${(pl+bw*iH).toFixed(1)}" x2="${(pl+bw*iH).toFixed(1)}" y1="${pt}" y2="${pt+ih}" class="hoje"/><text x="${(pl+bw*iH+4).toFixed(1)}" y="${pt+10}" class="t">previsto →</text>`:''}
 <polyline points="${real.join(' ')}" class="ac"/>${prev.length>1?`<polyline points="${prev.join(' ')}" class="ac dash"/>`:''}
 ${B.length<=62?B.map((b,i)=>`<circle cx="${X(i).toFixed(1)}" cy="${Y(b.ac).toFixed(1)}" r="${b.e||b.s?3.5:0}" class="acp${b.ac<0?' neg':''}"/>`).join(''):''}</svg></div>`}
PAGES.fluxo={async load(){return finBase()},
 html(){const d=D();const P=finPer();const F=fluxoDados(d,P);const fim=F.saldoIni+F.ent-F.sai;const menor=F.B.reduce((m,b)=>b.ac<m.ac?b:m,{ac:Infinity});const neg=F.B.find(b=>b.ac<0);
  const linhas=F.gran==='dia'?F.B.filter((b,i)=>b.e||b.s||i===0||b.hoje):F.B;
  return `<h1>Fluxo de caixa</h1><p class="sub">O que já foi pago ou recebido e, a partir de hoje, o previsto pelos vencimentos. ${F.gran==='mes'?'Períodos longos são mostrados mês a mês.':''}</p>
  <div class="toolbar">${finPerHTML()}<span class="sp"></span>${perm('financeiro','exportar')?`<button class="btn sm" data-act="fxCsv">Exportar CSV</button>`:''}</div>
  <div class="grid kpis">${kc('Saldo no início',BRL2(F.saldoIni),'em '+fD(addD(P.ini,-1))+' (realizado)')}${kc('Entradas',BRL2(F.ent),'realizadas + previstas')}${kc('Saídas',BRL2(F.sai),'realizadas + previstas')}${kc('Saldo no fim',BRL2(fim),'em '+fD(P.fim)+(P.fim>=T0?' (previsto)':''),fim<0?'bad':'ok')}${isFinite(menor.ac)?kc('Menor saldo',BRL2(menor.ac),menor.full,menor.ac<0?'bad':''):''}</div>
  ${neg?`<div class="note mt" style="background:var(--bad-soft)">O saldo fica <b>negativo em ${neg.full}</b> (${BRL2(neg.ac)}). Antecipe recebimentos ou renegocie pagamentos.</div>`:''}
  ${F.atr.length?`<div class="note mt">Há <b>${F.atr.length}</b> lançamento(s) vencidos e ainda em aberto (${BRL2(F.atr.filter(l=>l.tipo==='P').reduce((s,l)=>s+(+l.valor),0))} a pagar e ${BRL2(F.atr.filter(l=>l.tipo==='R').reduce((s,l)=>s+(+l.valor),0))} a receber). Eles não entram no fluxo até receberem baixa ou nova data de vencimento.</div>`:''}
  <div class="card tablewrap mt"><table><thead><tr><th>${F.gran==='dia'?'Dia':'Mês'}</th><th style="text-align:right">Entradas</th><th style="text-align:right">Saídas</th><th style="text-align:right">Saldo</th><th>Principais lançamentos</th></tr></thead><tbody>${linhas.map(b=>`<tr style="${b.hoje?'background:var(--accent-soft)':''}"><td>${b.full}${b.prev?' <span class="small muted">· previsto</span>':''}</td><td style="text-align:right;color:var(--ok)">${b.e?BRL2(b.e):''}</td><td style="text-align:right;color:var(--bad)">${b.s?BRL2(b.s):''}</td><td style="text-align:right;color:${b.ac<0?'var(--bad)':'inherit'}"><b>${BRL2(b.ac)}</b></td><td class="small">${b.L.slice(0,3).map(l=>esc((l.tipo==='R'?'+ ':'− ')+(fnFav(l.favorecido_id)||l.descricao))).join(' · ')}${b.L.length>3?` · +${b.L.length-3}`:''}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">Sem movimento no período.</td></tr>'}</tbody></table></div>
  <div class="card mt"><h3>Gráfico do fluxo de caixa</h3><p class="small muted">${P.lbl}${F.gran==='mes'?' · por mês':' · por dia'}. Passe o mouse sobre as barras para ver os valores.</p>${fluxoChart(F)}</div>`}};
