// ---------- DRE
function dreCalc(d,P,regime,obra){const cols=[];const nd=Math.round((P.fim-P.ini)/864e5)+1;
 if(nd>31)for(let x=new Date(P.ini.getFullYear(),P.ini.getMonth(),1);x<=P.fim;x=new Date(x.getFullYear(),x.getMonth()+1,1)){const a=x<P.ini?P.ini:new Date(x),b0=new Date(x.getFullYear(),x.getMonth()+1,0);cols.push({ini:a,fim:b0>P.fim?P.fim:b0,lbl:MESES[x.getMonth()]+'/'+String(x.getFullYear()).slice(2)})}
 const tot={ini:P.ini,fim:P.fim,lbl:'Total'};const C=cols.length>1?cols.concat([tot]):[tot];
 const base=(d.L||[]).filter(l=>l.pagador!=='Cliente'&&(regime==='caixa'?!!l.data_pagamento:true));
 const quando=l=>pdk(regime==='caixa'?l.data_pagamento:(l.competencia||l.vencimento));
 const parte=l=>{if(!obra)return 1;if(Array.isArray(l.rateio)&&l.rateio.length){const r=l.rateio.find(x=>x.obra_id===obra);return r?(+r.pct||0)/100:0}return l.obra_id===obra?1:0};
 const valor=l=>regime==='caixa'?+(l.valor_pago??l.valor):+(l.valor_bruto??l.valor);
 const ret=l=>regime==='caixa'||!l.retencoes?0:Object.values(l.retencoes).reduce((s,v)=>s+(+v||0),0);
 const M={};const add=(lin,cat,ci,v)=>{M[lin]=M[lin]||{};M[lin][cat]=M[lin][cat]||C.map(()=>0);M[lin][cat][ci]+=v};
 base.forEach(l=>{const q=quando(l);const f=parte(l);if(!f)return;const c=fnCat(l.categoria_id);const lin=l.categoria_id?dreLinha(c):(l.tipo==='R'?'outras_rec':'outras_desp');const cat=c.nome||(l.tipo==='R'?'Receita sem categoria':'Despesa sem categoria');
  C.forEach((col,ci)=>{if(q>=col.ini&&q<=col.fim){add(lin,cat,ci,valor(l)*f);const r=ret(l);if(r&&l.tipo==='R')add('deducao','Impostos retidos na fonte (pelo cliente)',ci,r*f)}})});
 const L=k=>C.map((_,ci)=>Object.values(M[k]||{}).reduce((s,a)=>s+a[ci],0));const sub=(a,b)=>a.map((v,i)=>v-b[i]),som=(a,b)=>a.map((v,i)=>v+b[i]);
 const rb=L('receita'),ded=L('deducao'),rl=sub(rb,ded),cus=L('custo'),lb=sub(rl,cus),dop=L('despesa'),ro=sub(lb,dop),rf=sub(L('fin_rec'),L('fin_desp')),ou=sub(L('outras_rec'),L('outras_desp')),rai=som(som(ro,rf),ou),ir=L('ir_csll'),res=sub(rai,ir);
 return {C,M,rb,ded,rl,cus,lb,dop,ro,rf,ou,rai,ir,res,fora:L('fora')}}
