const assLink=tk=>location.origin+location.pathname.replace(/[^/]*$/,'')+'assinar.html?t='+tk;
const novoTk=()=>Array.from(crypto.getRandomValues(new Uint8Array(32)),b=>b.toString(16).padStart(2,'0')).join('');
