const ctReais=(ct,cur)=>(ct||FN.ct||[]).filter(c=>(!c.virtual&&c.ativa!==false)||c.id===cur);
const catNome=(n,tp)=>((FN.cat||[]).find(c=>c.nome===n&&c.tipo===tp)||{}).id||null;
function trPares(L){const g={};(L||[]).filter(l=>l.transf_id).forEach(l=>{const x=g[l.transf_id]=g[l.transf_id]||{id:l.transf_id};if(l.tipo==='P')x.s=l;else x.e=l});return Object.values(g).filter(x=>x.s||x.e)}
PAGES.transf={async load(){return finBase()},
 html(){const d=D();const P=finPer();const ed=perm('financeiro','incluir');const fs=S.params.tfs||'todas';const q=(S.params.tfq||'').toLowerCase();
  const dt=x=>{const a=x.s||x.e;return pdk(a.data_pagamento||a.vencimento)};const pago=x=>!!((x.s||x.e).data_pagamento);
  const T0L=trPares(d.L).filter(x=>{const t=dt(x);return t>=P.ini&&t<=P.fim});
  const T=T0L.filter(x=>(fs==='todas'||(fs==='pagas'?pago(x):!pago(x)))&&(!q||[(x.s||x.e).descricao,x.s&&fnConta(x.s.conta_id),x.e&&fnConta(x.e.conta_id),String((x.s||x.e).valor).replace('.',',')].join(' ').toLowerCase().includes(q))).sort((a,b)=>dt(b)-dt(a));
  S._trVis=T;const tot=T.reduce((s,x)=>s+(+(x.s||x.e).valor||0),0);
  return `<h1>Transferências entre contas</h1><p class="sub">Dinheiro que só muda de conta dentro da Avante (aplicação, resgate, reforço de caixa de obra). Cada transferência gera a saída na conta de origem e a entrada na de destino. Fica fora da DRE e do fluxo consolidado, mas altera o saldo de cada conta.</p>
  <div class="toolbar"><input data-tff="tfq" placeholder="Buscar descrição, conta ou valor…" value="${esc(S.params.tfq||'')}" style="max-width:260px">${finPerHTML()}<span class="sp"></span>
   <div class="fp-m">${[['todas','Todas'],['pagas','Pagas'],['aberto','Em aberto']].map(([v,l])=>`<button class="${fs===v?'on':''}" data-act="trFs" data-v="${v}">${l}</button>`).join('')}</div>
   ${perm('financeiro','exportar')?'<button class="btn sm" data-act="trCsv">Exportar CSV</button> <button class="btn sm" data-act="trPrint">Imprimir</button>':''}${ed?' <button class="btn primary" data-act="trNova">+ Nova transferência</button>':''}</div>
  <div class="card tablewrap"><table><thead><tr><th>Data</th><th>Descrição</th><th>Conta de origem</th><th>Conta de destino</th><th class="num">Valor</th><th style="text-align:center">Pago</th><th>Conciliação</th><th></th></tr></thead><tbody>
  ${T.map(x=>{const a=x.s||x.e;const cs=l=>!l?pill('falta','bad'):l.conciliado?pill('ok','ok'):pill('pendente','');const conc=(x.s&&x.s.conciliado)||(x.e&&x.e.conciliado);
   return `<tr><td>${fD(a.data_pagamento||a.vencimento)}</td><td>${esc(String(a.descricao||'').replace(/^Transferência ·\s*/,''))}${a.arquivo_path?` <a class="lp-link small" data-act="trArq" data-id="${x.id}">anexo</a>`:''}</td><td>${esc(x.s?fnConta(x.s.conta_id):'—')}</td><td>${esc(x.e?fnConta(x.e.conta_id):'—')}</td><td class="num"><b>${BRL2(+a.valor)}</b></td>
   <td style="text-align:center"><input type="checkbox" data-trpago="${x.id}" ${pago(x)?'checked':''} ${perm('financeiro','editar')&&!conc?'':'disabled'} title="${conc?'Conciliada: desfaça a conciliação para alterar':'Marcar como paga'}" style="width:auto"></td>
   <td class="small">saída ${cs(x.s)} · entrada ${cs(x.e)}</td><td style="white-space:nowrap;text-align:right">${perm('financeiro','editar')?`<button class="btn sm" data-act="trEditar" data-id="${x.id}">Editar</button>`:''}</td></tr>`}).join('')||'<tr><td colspan="8" class="muted">Nenhuma transferência no período.</td></tr>'}</tbody>
  ${T.length?`<tfoot><tr><td colspan="4">${T.length} transferência(s)</td><td class="num">${BRL2(tot)}</td><td colspan="3"></td></tr></tfoot>`:''}</table></div>`}};
