const semAc=s=>String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toUpperCase();
function matchTarifa(e,T){if(!(+e.valor<0)||!T)return null;const ds=' '+semAc(e.descricao)+' '+semAc(e.documento)+' ';
 return T.find(r=>r.ativa!==false&&(!r.conta_id||r.conta_id===e.conta_id)&&(r.valor==null||Math.abs(Math.abs(+e.valor)-+r.valor)<0.011)&&String(r.padrao||'').split(';').map(x=>semAc(x)).filter(x=>x.trim()).some(p=>ds.includes(p)))||null}
async function tarLancar(e,r){const v=Math.abs(+e.valor);const ds=String(e.data).slice(0,10);
 const l=(await S.api.insert('fin_lancamentos',[{tipo:'P',descricao:r.nome+(e.descricao?' · '+e.descricao:''),categoria_id:r.categoria_id||null,obra_id:r.obra_id||null,conta_id:e.conta_id,vencimento:ds,competencia:ds,valor:v,data_pagamento:ds,valor_pago:v,documento:e.documento||null,pagador:'Empresa',conciliado:true}]))[0];
 await S.api.insert('fin_conciliacao',[{extrato_id:e.id,lancamento_id:l.id,baixou:false}]);return l}
async function tarAuto(ins){const d=D();if(!d||!(d.tar||[]).length||!ins.length)return 0;let n=0;const usados=new Set();
 for(const e of ins){const r=matchTarifa(e,d.tar);if(!r||!r.automatica)continue;if(concSug(e,d,usados))continue;await tarLancar(e,r);n++}return n}
