const OB_ST={'Em orçamento':'info','A iniciar':'','Em andamento':'ok','Paralisada':'warn','Concluída':'neutral','Cancelada':''};
const OB={};
const uuidv=()=>crypto.randomUUID?crypto.randomUUID():'xxxxxxxx-xxxx-4xxx-8xxx-xxxxxxxxxxxx'.replace(/x/g,()=>(Math.random()*16|0).toString(16));
const n4=v=>Math.round((+v||0)*10000)/10000;
const fQi=v=>v==null||v===''?'':String(+v).replace('.',',');
const fQ=v=>v==null||v===''?'':(+v).toLocaleString('pt-BR',{maximumFractionDigits:4});
async function obBase(extra){const[clientes,orcs,meds]=await Promise.all([S.api.select('clientes',{cols:'id,nome,cpf_cnpj,cidade,email,telefone,endereco,uf',order:['nome']}).catch(()=>[]),S.api.select('orcamentos',{order:['criado_em',false]}).catch(e=>/orcamentos/.test(e.message)?null:[]),S.api.select('obra_medicoes',{cols:'id,orcamento_id,obra_id,numero,data,status,valor,periodo_fim'}).catch(()=>[])]);
 Object.assign(OB,{clientes,orcs,meds});return {clientes,orcs,meds}}
const obCli=id=>((OB.clientes||[]).find(c=>c.id===id)||{}).nome||'';
const obraObj=id=>(S.ref.obras||[]).find(o=>o.id===id)||{};
// orçamento principal da obra: o vendido; senão o mais recente
const orcDaObra=(id,orcs)=>{const L=(orcs||OB.orcs||[]).filter(o=>o.obra_id===id&&o.status_proposta!=='Cancelada'&&o.status_proposta!=='Perdida');return L.find(o=>o.status_proposta==='Venda')||L[0]||null};
// totais de um orçamento a partir dos itens (árvore)
function orcCalc(orc,itens){const bdiG=+orc.bdi||0;const byPai={};itens.forEach(i=>(byPai[i.pai_id||'']=byPai[i.pai_id||'']||[]).push(i));Object.values(byPai).forEach(L=>L.sort((a,b)=>a.ordem-b.ordem));const T={};const num={};
 const walk=(pai,pref)=>(byPai[pai]||[]).reduce((acc,i,k)=>{const n=pref?pref+'.'+(k+1):String(k+1);num[i.id]=n;let c,p;if(i.tipo==='item'){const b=i.bdi!=null&&i.bdi!==''?+i.bdi:bdiG;const cu=+i.custo_unit||0,q=+i.quantidade||0;c=cu*q;const pu=Math.round(cu*(1+b/100)*100)/100;p=Math.round(pu*q*100)/100;c=Math.round(c*100)/100;T[i.id]={c,p,pu,b}}else{const r=walk(i.id,n);c=r.c;p=r.p;T[i.id]={c,p}}acc.c+=c;acc.p+=p;return acc},{c:0,p:0});
 const tot=walk('','');return {T,num,byPai,custo:tot.c,preco:tot.p,bdiEf:tot.c?(tot.p/tot.c-1)*100:bdiG}}

// ---------- leitor de planilhas sem biblioteca externa: XLSX (zip + XML) e CSV
async function lerPlanilha(file){const buf=await file.arrayBuffer();const u8=new Uint8Array(buf);if(u8[0]===0x50&&u8[1]===0x4b)return lerXlsx(u8);if(/\.xls$/i.test(file.name))throw new Error('Arquivo .xls antigo: abra no Excel e salve como .xlsx ou CSV.');return csvRows(impTexto(buf))}
function csvRows(t){const L=t.split(/\r\n|\r|\n/);const sep=[';','\t',','].map(s=>[s,(L[0]||'').split(s).length]).sort((a,b)=>b[1]-a[1])[0][0];return L.map(l=>{const o=[];let cur='',q=false;for(const ch of l){if(ch==='"'){q=!q;continue}if(ch===sep&&!q){o.push(cur);cur='';continue}cur+=ch}o.push(cur);return o.map(x=>x.trim())})}
async function unzip(u8,want){const dv=new DataView(u8.buffer,u8.byteOffset,u8.byteLength);let e=u8.length-22;while(e>=0&&dv.getUint32(e,true)!==0x06054b50)e--;if(e<0)throw new Error('Arquivo XLSX inválido.');
 const n=dv.getUint16(e+10,true);let p=dv.getUint32(e+16,true);const out={};const td=new TextDecoder();
 for(let k=0;k<n;k++){const met=dv.getUint16(p+10,true),cs=dv.getUint32(p+20,true),fl=dv.getUint16(p+28,true),xl=dv.getUint16(p+30,true),cl=dv.getUint16(p+32,true),lo=dv.getUint32(p+42,true);const name=td.decode(u8.subarray(p+46,p+46+fl));p+=46+fl+xl+cl;
  if(!want(name))continue;const ds=lo+30+dv.getUint16(lo+26,true)+dv.getUint16(lo+28,true);const raw=u8.subarray(ds,ds+cs);let data;
  if(met===0)data=raw;else{const st=new Blob([raw]).stream().pipeThrough(new DecompressionStream('deflate-raw'));data=new Uint8Array(await new Response(st).arrayBuffer())}out[name]=td.decode(data)}return out}
async function lerXlsx(u8){const F=await unzip(u8,n=>/^xl\/(sharedStrings\.xml|workbook\.xml|_rels\/workbook\.xml\.rels|worksheets\/sheet\d+\.xml)$/.test(n));const P=s=>new DOMParser().parseFromString(String(s).replace(/^\uFEFF/,''),'application/xml');const TG=(el,n)=>el.getElementsByTagNameNS('*',n);
 const ss=F['xl/sharedStrings.xml']?[...TG(P(F['xl/sharedStrings.xml']),'si')].map(si=>[...TG(si,'t')].map(t=>t.textContent).join('')):[];
 let alvo=Object.keys(F).filter(n=>/worksheets\/sheet/.test(n)).sort((a,b)=>parseInt(a.match(/\d+/))-parseInt(b.match(/\d+/)))[0];
 try{const wb=P(F['xl/workbook.xml']);const s1=TG(wb,'sheet')[0];const rid=s1.getAttribute('r:id')||s1.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id');const rel=[...TG(P(F['xl/_rels/workbook.xml.rels']),'Relationship')].find(r=>r.getAttribute('Id')===rid);if(rel){const t='xl/'+rel.getAttribute('Target').replace(/^\/?xl\//,'');if(F[t])alvo=t}}catch(e){}
 if(!alvo)throw new Error('Nenhuma planilha encontrada no arquivo.');const col=r=>{const m=r.match(/^[A-Z]+/)[0];let n=0;for(const ch of m)n=n*26+ch.charCodeAt(0)-64;return n-1};const rows=[];
 let rAnt=-1;[...TG(P(F[alvo]),'row')].forEach(r=>{const ri=r.getAttribute('r')?+r.getAttribute('r')-1:rAnt+1;rAnt=ri;const o=rows[ri]=[];let cAnt=-1;[...TG(r,'c')].forEach(c=>{const t=c.getAttribute('t');const v=TG(c,'v')[0];let x=v?v.textContent:'';if(t==='s')x=ss[+x]||'';else if(t==='inlineStr')x=[...TG(c,'t')].map(z=>z.textContent).join('');const ci=c.getAttribute('r')?col(c.getAttribute('r')):cAnt+1;cAnt=ci;o[ci]=x})});
 return Array.from(rows,r=>Array.from(r||[],x=>x==null?'':String(x).trim()))}
const numPl=v=>{if(v==null||v==='')return null;let s=String(v).replace(/R\$|\s/g,'');if(/^-?\d+(\.\d+)?(e-?\d+)?$/i.test(s))return +s;if(/,\d+$/.test(s))s=s.replace(/\./g,'').replace(',','.');else s=s.replace(/,/g,'');const n=+s;return isFinite(n)?n:null};

