  const dg=g('doc').replace(/\D/g,'');if(dg&&dg.length!==11&&dg.length!==14){box.querySelector('.cl-err').textContent='CPF deve ter 11 dígitos e CNPJ 14.';return}const pj=dg.length===14||(!dg&&/\b(LTDA|S\.?A\.?|EIRELI|ME|EPP|CONS[OÓ]RCIO|PREFEITURA|ENERGIA|ENGENHARIA)\b/.test(nome));
  const doc=dg.length===14?dg.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/,'$1.$2.$3/$4-$5'):dg.length===11?dg.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/,'$1.$2.$3-$4'):null;
  if(doc&&(OB.clientes||[]).some(c=>String(c.cpf_cnpj||'').replace(/\D/g,'')===dg)){const c=OB.clientes.find(c=>String(c.cpf_cnpj||'').replace(/\D/g,'')===dg);sel.value=c.id;box.remove();toast('Cliente já cadastrado: '+c.nome+'. Selecionado.');return}
