  const row={codigo:v('#obC')||null,nome:v('#obN').toUpperCase(),status:st,cliente_id:(v('#obCl')==='_novo'?null:v('#obCl')||null),cidade:v('#obCi')||null,endereco:v('#obE')||null,data_inicio:v('#obI')||null,data_prev_fim:v('#obF')||null,valor_contrato:numBR(v('#obV')),centro_custo:v('#obCC')||null,responsavel_id:v('#obR')||null,observacao:v('#obO')||null,contrato_numero:v('#obCt')||null,fiscal_nome:v('#obFn')||null,fiscal_empresa:v('#obFe')||null,fiscal_telefone:v('#obFt')?(celDig(v('#obFt'))?celFmt(v('#obFt')):v('#obFt')):null,fiscal_email:v('#obFm')||null,ativa:!['Concluída','Cancelada'].includes(st)};
