PAGES.obrasgestao={async load(){const[b,itens,rdo,ct,cm,fin,rf]=await Promise.all([obBase(),S.api.select('orc_itens',{cols:'id,orcamento_id,pai_id,ordem,tipo,quantidade,custo_unit,bdi'}).catch(()=>[]),S.api.select('obra_diarios',{cols:'obra_id,data,status',gte:{data:dk(addD(T0,-14))}}).catch(()=>[]),S.api.select('obra_contratos').catch(()=>[]),S.api.select('contrato_medicoes',{cols:'contrato_id,valor,status'}).catch(()=>[]),perm('financeiro','ver')?finBase().catch(()=>null):null,perm('rateio','ver')?S.api.select('rateio_fechamento',{cols:'obra_id,total'}).catch(()=>null):null]);return Object.assign(b,{itens,rdo,ct,cm,fin,rf})},
 html(){const d=D();const O=obrasUser().filter(o=>o.nome!=='ESCRITÓRIO'&&!['Concluída','Cancelada'].includes(o.status));const uteis=[];for(let x=addD(T0,-1);uteis.length<5;x=addD(x,-1))if(carga(x)>0)uteis.push(dk(x));
  if(d.fin)FN.cat=d.fin.cat;const rows=O.map(o=>{const orc=orcDaObra(o.id,d.orcs);let orcado=null,custoOrc=null;if(orc){const r=orcCalc(orc,(d.itens||[]).filter(i=>i.orcamento_id===orc.id));orcado=r.preco;custoOrc=r.custo}const contrato=+o.valor_contrato||orcado||0;
   const med=(d.meds||[]).filter(m=>m.obra_id===o.id&&!['Rascunho','Cancelada'].includes(m.status)).reduce((s,m)=>s+(+m.valor||0),0);
   let custo=null;if(d.fin){custo=0;(d.fin.L||[]).filter(l=>l.tipo==='P'&&!isTransf(l)&&!l._v&&!fnCat(l.categoria_id).ja_apurado).forEach(l=>fnObras(l).forEach(x=>{if(x.obra===o.id)custo+=x.v}));if(d.rf)custo+=d.rf.filter(r=>r.obra_id===o.id).reduce((s,r)=>s+(+r.total||0),0)}
   const rdo=uteis.filter(u=>(d.rdo||[]).some(r=>r.obra_id===o.id&&String(r.data).slice(0,10)===u)).length;const cts=(d.ct||[]).filter(c=>c.obra_id===o.id&&c.status==='Ativo');const ctV=cts.reduce((s,c)=>s+ctTotal(c),0),ctM=(d.cm||[]).filter(m=>cts.some(c=>c.id===m.contrato_id)&&m.status!=='Cancelada'&&m.status!=='Rascunho').reduce((s,m)=>s+(+m.valor||0),0);
   return {o,orc,contrato,custoOrc,med,custo,rdo,ctV,ctM}});
  const sum=k=>rows.reduce((s,r)=>s+(+r[k]||0),0);
  return `<h1>Gestão de obras</h1><p class="sub">Visão geral das obras em execução: valor contratado, medido, custo realizado, diário de obras e contratos de empreiteiros.</p>
  <div class="grid kpis">${kc('Obras em execução',rows.length,rows.filter(r=>r.o.data_prev_fim&&pdk(r.o.data_prev_fim)<T0).length+' com prazo vencido')}${kc('Contratado',BRL2(sum('contrato')),'soma das obras')}${kc('Medido',BRL2(sum('med')),sum('contrato')?N(sum('med')/sum('contrato')*100,1)+'% do contratado':'')}${d.fin?kc('Custo realizado',BRL2(sum('custo')),'financeiro + folha rateada'+(d.rf?'':' (sem acesso à folha)')):''}${kc('Diário em dia',rows.filter(r=>r.rdo>=5).length+' de '+rows.length,'RDO nos últimos 5 dias úteis',rows.some(r=>r.rdo<3)?'warn':'ok')}</div>
  <div class="card mt tablewrap"><table><thead><tr><th>Obra</th><th class="num">Contratado</th><th class="num">Medido</th><th style="width:13%">Avanço</th>${d.fin?'<th class="num">Custo realizado</th><th class="num">Resultado</th>':''}<th class="num">Empreiteiros (medido/contratado)</th><th class="num">RDO (5 dias)</th><th>Prazo</th></tr></thead><tbody>
  ${rows.map(r=>{const p=r.contrato?Math.min(100,r.med/r.contrato*100):0;const res=r.custo!=null?r.med-r.custo:null;return `<tr style="cursor:pointer" data-act="go" data-r="obradet" data-id="${r.o.id}"><td><b>${esc(r.o.nome)}</b><div class="small muted">${esc(obCli(r.o.cliente_id)||'')}${r.orc?' · orç. '+esc(r.orc.codigo):''}</div></td><td class="num">${r.contrato?BRL2(r.contrato):'—'}</td><td class="num">${BRL2(r.med)}</td>
   <td><div class="hb-t" title="${N(p,1)}%"><div class="hb-f" style="width:${Math.max(1,p).toFixed(1)}%"></div></div><span class="small muted">${N(p,1)}%</span></td>${d.fin?`<td class="num">${BRL2(r.custo)}</td><td class="num" style="color:${res<0?'var(--bad)':'var(--ok)'}"><b>${BRL2(res)}</b></td>`:''}
   <td class="num">${r.ctV?`${BRL2(r.ctM)} / ${BRL2(r.ctV)}`:'—'}</td><td class="num">${r.rdo<3?`<b style="color:var(--bad)">${r.rdo}</b>`:r.rdo}/5</td><td>${r.o.data_prev_fim?(pdk(r.o.data_prev_fim)<T0?pill(fD(r.o.data_prev_fim),'bad'):fD(r.o.data_prev_fim)):'—'}</td></tr>`}).join('')||'<tr><td colspan="9" class="muted">Nenhuma obra em execução.</td></tr>'}</tbody></table></div>
  <p class="small muted mt">Resultado = medido ao cliente − custo realizado (contas a pagar da obra + folha rateada pelo ponto). Não inclui impostos sobre o faturamento nem custos administrativos.</p>`}};

