// ================================================================ OBRAS · DIÁRIO DE OBRAS (RDO): lista, preenchimento, aprovação, PDF e apropriação no ponto
const CLIMAS=['Bom','Nublado','Chuvoso'];const CONDS=['Praticável','Impraticável'];const ATV_ST=['Iniciada','Em andamento','Finalizada','Paralisada'];
const OC_TIPOS=['Visita do fiscal','Condição climática','Acidente / incidente','Paralisação','Entrega de material','Falta de material ou equipamento','Visita do cliente','Outros'];
const RDO_ST={'Rascunho':'warn','Em análise':'info','Aprovado':'ok','Reprovado':'bad','Concluído':'info'};
const hmMin=s=>{if(!s)return null;const[h,m]=String(s).slice(0,5).split(':').map(Number);return isNaN(h)?null:h*60+(m||0)};
const minHM=m=>m==null?'—':String(Math.floor(m/60)).padStart(2,'0')+':'+String(Math.round(m%60)).padStart(2,'0');
function rdoHoras(r){const a=hmMin(r.hora_ini),b=hmMin(r.hora_fim);if(a==null||b==null||b<=a)return null;return Math.max(0,b-a-(r.intervalo_min??60))}
const rdoEfetivo=r=>(r.mao_obra||[]).length+(r.efetivo||[]).reduce((s,e)=>s+(+e.qtd||0),0);
const rdoLink=tk=>location.origin+location.pathname.replace(/[^/]*$/,'')+'aprovar-rdo.html?t='+tk;

// ---------------------------------------------------------------- LISTA (padrão Mais Controle) + CALENDÁRIO
PAGES.diario={async load(){const obras=obrasUser().filter(o=>o.nome!=='ESCRITÓRIO');if(S.params.id&&!S.params.do)S.params.do=S.params.id;if(S.params.do&&!obras.some(o=>o.id===S.params.do))S.params.do='';
 const ini=S.params.di||dk(addD(T0,-90)),fim=S.params.df||dk(addD(T0,1));S.params.di=ini;S.params.df=fim;const f={cols:'id,numero,obra_id,data,status,autor_id,importado,aprov_int,aprov_fiscal,clima_manha,clima_tarde,cond_manha,cond_tarde,mao_obra,efetivo,atividades,equipamentos,ocorrencias_l',gte:{data:ini},lte:{data:fim},order:['data',false]};if(S.params.do)f.eq={obra_id:S.params.do};
 const[L]=await Promise.all([S.api.select('obra_diarios',f).catch(e=>/obra_diarios/.test(e.message)?null:[]),obBase(),tfEquipe()]);return {obras,L}},
 html(){const d=D();if(d.L===null)return '<div class="note">Rode os ajustes 22 e 23 no Supabase.</div>';const tab=S.params.dt||'lista';const st=S.params.dst||'';const q=(S.params.dq||'').toLowerCase();const ed=perm('engenharia','incluir');
  const L=(d.L||[]).filter(r=>(!st||r.status===st)&&(!q||[r.numero,obraNome(r.obra_id),JSON.stringify(r.mao_obra||[]),JSON.stringify(r.atividades||[]),JSON.stringify(r.equipamentos||[]),JSON.stringify(r.ocorrencias_l||[])].join(' ').toLowerCase().includes(q)));
  const top=`<h1>Diário de obras</h1><p class="sub">Relatório diário de obra (RDO): clima, mão de obra nominal (ligada ao ponto), equipamentos, atividades do orçamento, ocorrências, comentários e fotos, com aprovação assinada da fiscalização.</p>
  <div class="tabs">${[['lista','Lista de diários'],['cal','Calendário da obra']].map(([v,l])=>`<button class="btn sm ${tab===v?'primary':''}" data-act="rdoTab" data-t="${v}">${l}</button>`).join('')}</div>
  <div class="toolbar"><input data-dq="1" placeholder="Buscar: funcionário, equipamento, atividade…" value="${esc(S.params.dq||'')}" style="max-width:260px"><input type="date" data-rdf="di" value="${S.params.di}" style="width:auto"><span class="small muted">até</span><input type="date" data-rdf="df" value="${S.params.df}" style="width:auto">
   <select data-rdf="do"><option value="">Todas as obras</option>${d.obras.map(o=>`<option value="${o.id}" ${o.id===S.params.do?'selected':''}>${esc(o.nome)}</option>`).join('')}</select><select data-rdo2="dst"><option value="">Todos os status</option>${Object.keys(RDO_ST).filter(s=>s!=='Concluído').map(s=>`<option ${s===st?'selected':''}>${s}</option>`).join('')}</select><span class="sp"></span>${ed?'<button class="btn" data-act="rdoImportMC">Importar do Mais Controle</button> <button class="btn primary" data-act="rdoNovoModal">+ Novo RDO</button>':''}</div>`;
  if(tab==='cal')return top+rdoCal(d);
  return top+`<div class="card tablewrap"><table><thead><tr><th>Número</th><th>Data</th><th>Obra</th><th>Cliente</th><th class="num">Efetivo</th><th>Status</th><th>Criado por</th><th>Resp. aprovação</th></tr></thead><tbody>
  ${L.map(r=>`<tr style="cursor:pointer" data-act="go" data-r="diariodet" data-id="${r.id}"><td><b>${r.numero||''}</b></td><td>${fD(r.data)}</td><td>${esc(obraNome(r.obra_id))}</td><td class="small">${esc(obCli(obraObj(r.obra_id).cliente_id)||'')}</td><td class="num">${rdoEfetivo(r)}</td><td>${pill(r.status,RDO_ST[r.status])}</td><td class="small">${esc(tfNome(r.autor_id)||(r.importado&&r.importado.criado_por)||'—')}${r.importado?' <span class="tag">MC</span>':''}</td><td class="small">${r.aprov_fiscal?esc(r.aprov_fiscal.nome)+(r.aprov_fiscal.decisao==='Reprovado'?' (reprovou)':''):''}</td></tr>`).join('')||'<tr><td colspan="8" class="muted">Nenhum RDO no período.</td></tr>'}</tbody></table></div>`}};
function rdoCal(d){const ob=S.params.do;if(!ob)return '<div class="note">Escolha uma obra para ver o calendário.</div>';const k=S.params.dm||dk(T0).slice(0,7);const[y,m]=k.split('-').map(Number);const dias=new Date(y,m,0).getDate();const by={};(d.L||[]).forEach(r=>{if(r.obra_id===ob)by[String(r.data).slice(0,10)]=r});const ed=perm('engenharia','incluir');
 const cel=[];const pri=new Date(y,m-1,1).getDay();for(let i=0;i<pri;i++)cel.push('<div></div>');for(let i=1;i<=dias;i++){const dt=new Date(y,m-1,i);const kk=dk(dt);const r=by[kk];const util=carga(dt)>0;const fut=dt>T0;
  cel.push(`<div class="rdo-d ${r?(r.status==='Aprovado'?'ok':r.status==='Reprovado'?'falta':'rs'):(!fut&&util?'falta':'')} ${fut?'fut':''}" ${r?`data-act="go" data-r="diariodet" data-id="${r.id}"`:(!fut&&ed?`data-act="rdoNovo" data-dt="${kk}" data-ob="${ob}"`:'')}><b>${i}${r?' · #'+r.numero:''}</b>${r?`<span>${esc(r.status)}</span><span>${rdoEfetivo(r)} pessoas</span>`:(!fut&&util?'<span>sem RDO</span>':'')}</div>`)}
 return `<div class="toolbar"><select data-rdo2="dm">${MESES12().map(x=>`<option value="${x}" ${x===k?'selected':''}>${mesLbl(x)}</option>`).join('')}</select></div><div class="card"><div class="rdo-cal">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(x=>`<div class="rdo-w">${x}</div>`).join('')}${cel.join('')}</div></div><p class="small muted mt">O calendário usa o período filtrado acima; ajuste as datas para ver meses anteriores.</p>`}
FIELD.push(ev=>{const t=ev.target;if(!t.dataset)return false;if(t.dataset.rdf){if(ev.type==='change'){S.params[t.dataset.rdf]=t.value;if(t.dataset.rdf==='do')S.params.id='';reload()}return true}
 if(t.dataset.rdo2){if(ev.type==='change'){S.params[t.dataset.rdo2]=t.value;if(t.dataset.rdo2==='dm'){S.params.di=t.value+'-01';S.params.df=dk(new Date(+t.value.slice(0,4),+t.value.slice(5,7),0));reload();return true}render()}return true}
 if(t.dataset.dq){if(ev.type==='input'){S.params.dq=t.value;const pos=t.selectionStart;render();const n=document.querySelector('[data-dq]');if(n){n.focus();try{n.setSelectionRange(pos,pos)}catch(e){}}}return true}return false});
Object.assign(ACT,{
 rdoTab:t=>{S.params.dt=t.dataset.t;render()},
 rdoNovoModal:()=>{const obras=obrasUser().filter(o=>o.nome!=='ESCRITÓRIO');openModal(`<h2>Novo RDO</h2><label>Obra *</label><select id="rnO">${obras.map(o=>`<option value="${o.id}" ${o.id===S.params.do?'selected':''}>${esc(o.nome)}</option>`).join('')}</select><label>Data *</label><input type="date" id="rnD" value="${dk(T0)}" max="${dk(T0)}">
  <p class="small muted">Equipamentos e atividades em andamento do último RDO da obra são copiados; a mão de obra vem do ponto do dia.</p><div class="modal-actions"><button class="btn" data-act="close">Cancelar</button><button class="btn primary" data-act="rdoNovo">Criar</button></div>`)},
 rdoNovo:async t=>{const ob=t.dataset.ob||($('#rnO')||{}).value;const dt=t.dataset.dt||($('#rnD')||{}).value;if(!ob||!dt)return;closeModal();const ex=await S.api.select('obra_diarios',{eq:{obra_id:ob,data:dt}}).catch(()=>[]);if(ex[0]){go('diariodet',{id:ex[0].id});return}
  const ant=(await S.api.select('obra_diarios',{eq:{obra_id:ob},lte:{data:dk(addD(pdk(dt),-1))},order:['data',false],limit:1}).catch(()=>[]))[0];
  const r=(await S.api.insert('obra_diarios',[{obra_id:ob,data:dt,status:'Rascunho',clima_manha:'Bom',clima_tarde:'Bom',cond_manha:'Praticável',cond_tarde:'Praticável',praticavel:true,mao_obra:[],efetivo:[],equipamentos:ant?ant.equipamentos||[]:[],atividades:ant?(ant.atividades||[]).filter(a=>a.status!=='Finalizada'&&a.status!=='Concluída').map(a=>Object.assign({},a,{status:'Em andamento',comentario:''})):[],ocorrencias_l:[],fotos:[],
   dds_ini:ant?ant.dds_ini:'07:00',dds_fim:ant?ant.dds_fim:'07:10',hora_ini:ant?ant.hora_ini:'07:10',hora_fim:ant?ant.hora_fim:(pdk(dt).getDay()===5?'16:00':'17:00'),intervalo_min:ant?ant.intervalo_min??60:60,autor_id:S.user.id}]))[0];
  S._rdoPuxar=r.id;go('diariodet',{id:r.id})}});

