function sigInit(sel){const c=$(sel);if(!c)return;const r=c.getBoundingClientRect();const k=window.devicePixelRatio||1;c.width=r.width*k;c.height=r.height*k;const x=c.getContext('2d');x.scale(k,k);x.lineWidth=2.2;x.lineCap='round';x.lineJoin='round';x.strokeStyle='#0b2a4a';c._pts=0;let des=false,last=null;const pos=e=>{const b=c.getBoundingClientRect();return [e.clientX-b.left,e.clientY-b.top]};
 c.onpointerdown=e=>{des=true;last=pos(e);c.setPointerCapture(e.pointerId);e.preventDefault()};c.onpointermove=e=>{if(!des)return;const p=pos(e);x.beginPath();x.moveTo(last[0],last[1]);x.lineTo(p[0],p[1]);x.stroke();last=p;c._pts++;e.preventDefault()};c.onpointerup=c.onpointercancel=c.onpointerleave=()=>{des=false}}
