 cmLancar:async t=>{const {c,ms,fav}=D();const m=ms.find(x=>x.id===t.dataset.id);openModal(`<h2>Lançar no contas a pagar</h2><p>Medição ${m.numero} · ${esc((fav.find(f=>f.id===c.favorecido_id)||{}).nome||'')} · líquido <b>${BRL2(+m.liquido)}</b></p><label>Vencimento *</label><input type="date" id="clV" value="${dk(addD(T0,7))}"><p class="small muted">Categoria "Serviços terceirizados e empreiteiros", centro de custo ${esc(obraNome(c.obra_id))}. A retenção técnica (${BRL2(+m.retencao)}) fica registrada na medição para devolução no fim do contrato.</p><div id="err" class="err"></div><div class="modal-actions"><button class="btn" data-act="close">Cancelar</button><button class="btn primary" data-act="cmLancarOk" data-id="${m.id}">Lançar</button></div>`)},
