  <table><tr><td><b>Contratante:</b> ${esc(emp.razao_social||'Avante Engenharia')}</td><td><b>Contratado:</b> ${esc(f.nome||'')} ${f.cpf_cnpj?'· '+esc(f.cpf_cnpj):''}</td><td><b>Obra:</b> ${esc(obraNome(c.obra_id))}</td></tr></table>
