// ================================================================ OBRAS · IMPORTAR RDOs DO MAIS CONTROLE (PDF exportado)
const MC_MES={jan:0,fev:1,mar:2,abr:3,mai:4,jun:5,jul:6,ago:7,set:8,out:9,nov:10,dez:11};
// lê texto (linha a linha, com a página de cada linha) e as fotos de um PDF
async function rdoPdfLer(file,comFotos){if(!_pdfjs){_pdfjs=await import(new URL('lib/pdf.min.mjs',location.href).href);_pdfjs.GlobalWorkerOptions.workerSrc=new URL('lib/pdf.worker.min.mjs',location.href).href}
 const doc=await _pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;const linhas=[],fotos=[];
 for(let p=1;p<=doc.numPages;p++){const pg=await doc.getPage(p);const tc=await pg.getTextContent();const L={};tc.items.forEach(it=>{if(!it.str||!it.str.trim())return;const y=Math.round(it.transform[5]/3)*3;(L[y]=L[y]||[]).push({x:it.transform[4],s:it.str})});
  Object.keys(L).map(Number).sort((a,b)=>b-a).forEach(y=>linhas.push({p,t:L[y].sort((a,b)=>a.x-b.x).map(i=>i.s).join(' ').replace(/\s+/g,' ').trim()}));
  if(!comFotos)continue;try{const ops=await pg.getOperatorList();const vistos=new Set();for(let i=0;i<ops.fnArray.length;i++){if(ops.fnArray[i]!==_pdfjs.OPS.paintImageXObject)continue;const id=ops.argsArray[i][0];if(vistos.has(id))continue;vistos.add(id);
   const img=await new Promise(ok=>{const src=String(id).startsWith('g_')?pg.commonObjs:pg.objs;try{src.get(id,ok)}catch(e){ok(null)}setTimeout(()=>ok(null),4000)});if(!img||img.width<300||img.height<200||img.width/img.height>2.4||img.height/img.width>2.4)continue;
   const c=document.createElement('canvas');const k=Math.min(1,1400/Math.max(img.width,img.height));c.width=Math.round(img.width*k);c.height=Math.round(img.height*k);const x=c.getContext('2d');
   if(img.bitmap)x.drawImage(img.bitmap,0,0,c.width,c.height);else if(img.data){const t=document.createElement('canvas');t.width=img.width;t.height=img.height;const id2=t.getContext('2d').createImageData(img.width,img.height);const d=img.data;
    if(d.length===img.width*img.height*4)id2.data.set(d);else if(d.length===img.width*img.height*3){for(let a=0,b=0;a<d.length;a+=3,b+=4){id2.data[b]=d[a];id2.data[b+1]=d[a+1];id2.data[b+2]=d[a+2];id2.data[b+3]=255}}else continue;t.getContext('2d').putImageData(id2,0,0);x.drawImage(t,0,0,c.width,c.height)}else continue;
   const blob=await new Promise(ok=>c.toBlob(ok,'image/jpeg',.82));if(blob)fotos.push({p,blob})}}catch(e){console.warn('fotos',e)}}
 return {linhas,fotos,paginas:doc.numPages}}
const RUIDO=/^(Relat[oó]rio de Di[aá]rio de Obra|AVANTE ENGENHARIA|CNPJ:|.*@.*\s-\s.*|Prazo:|\d+ dia\(s\) decorridos|In[ií]cio: \d{2}\/\d{2}\/\d{4}|Fotos$|P[aá]gina \d+)/i;
function rdoMcParse(lido){const L=lido.linhas;const blocos=[];let cur=null;
 L.forEach((l,i)=>{const m=l.t.match(/^#\s*(\d+)\s*-\s*(\d{1,2})\s+([a-zç]{3})[a-z]*\.?\s+(\d{4})/i);if(m){const pre=L.slice(Math.max(0,i-3),i).filter(x=>x.p===l.p&&/Status:|Criado por|Aprovado por/i.test(x.t));if(cur)cur.linhas=cur.linhas.filter(x=>!pre.includes(x));cur={numero:+m[1],data:dk(new Date(+m[4],MC_MES[semAc(m[3]).toLowerCase().slice(0,3)]??0,+m[2])),linhas:pre.concat([l]),p0:l.p,p1:l.p};blocos.push(cur)}else if(cur){cur.linhas.push(l);cur.p1=l.p}});
 return blocos.map(b=>{const T=b.linhas.map(x=>x.t);const all=T.join('\n');const r={numero:b.numero,data:b.data,p0:b.p0,p1:b.p1,mao_obra:[],efetivo:[],equipamentos:[],atividades:[],ocorrencias_l:[],avisos:[]};
  r.status=/Status:\s*Aprovado/i.test(all)?'Aprovado':/Status:\s*Reprovado/i.test(all)?'Reprovado':'Em análise';
  const cp=all.match(/Criado por:\s*([^|\n]+)/i);r.criado_por=cp?cp[1].trim():null;const ap=all.match(/Aprovado por:\s*([^\n]*)\n?([^\n]*)/i);if(ap){r.aprovado_por=(ap[1].trim()||ap[2].trim()).replace(/^Cliente:.*/,'')||null}
  const g=(re)=>{const m=all.match(re);return m?m[1].trim():null};r.cliente=g(/Cliente:\s*([^\n]+)/i);r.obra=g(/Obra:\s*([^\n]+)/i);r.endereco=g(/Endere[cç]o:\s*([^\n]+)/i);r.contrato=g(/Contrato n[°º]?:\s*([^\s-]+)/i);
  const tm=all.match(/Manh[aã]\s*\(([^)]+)\)/i),tt=all.match(/Tarde\s*\(([^)]+)\)/i);r.cond_manha=tm&&/impratic/i.test(tm[1])?'Impraticável':'Praticável';r.cond_tarde=tt&&/impratic/i.test(tt[1])?'Impraticável':'Praticável';
  // seções
  const idx=re=>T.findIndex(t=>re.test(t));const SEC=[['mo',/^M[aã]o de obra$/i],['eq',/^Equipamentos$/i],['at',/^Atividades\b/i],['oc',/^Ocorr[eê]ncias\b/i],['co',/^Coment[aá]rios$/i],['fo',/^Fotos$/i]];
  const pos=SEC.map(([k,re])=>[k,idx(re)]).filter(x=>x[1]>=0).sort((a,b)=>a[1]-b[1]);const sec={};pos.forEach(([k,i],j)=>{const fim=j+1<pos.length?pos[j+1][1]:T.length;sec[k]=T.slice(i+1,fim).filter(t=>!RUIDO.test(t)&&!/^Contrato n[°º]/i.test(t))});
  (sec.mo||[]).forEach(t=>{const m=t.match(/^(\d+)\s+(.+)$/);if(!m)return;const q=+m[1];const ps=m[2].split(/\s+-\s+/).map(s=>s.trim()).filter(Boolean);
   if(q===1&&ps.length>=2&&/^[A-ZÀ-Ú][A-ZÀ-Ú\s.'-]{5,}$/.test(ps[ps.length-1]))r.mao_obra.push({nome:ps[ps.length-1],funcao:ps[0],regime:ps.length>2?ps.slice(1,-1).join(' - '):null});else r.efetivo.push({funcao:ps.join(' - '),qtd:q,empresa:''})});
  (sec.eq||[]).forEach(t=>{const m=t.match(/^(\d+)\s+(.+)$/);if(m)r.equipamentos.push({qtd:+m[1],nome:m[2],situacao:'Operando'});else if(r.equipamentos.length)r.equipamentos[r.equipamentos.length-1].nome+=' '+t});
  let a=null,modo='t';(sec.at||[]).forEach(t=>{if(/^\d+(\.\d+)*\s+-\s+/.test(t)){a={texto:t,status:'Em andamento',comentario:''};r.atividades.push(a);modo='t';return}if(!a)return;const s=t.match(/^Status:\s*(.+)$/i);if(s){a.status=/finaliz|conclu/i.test(s[1])?'Finalizada':/paralis/i.test(s[1])?'Paralisada':/inici/i.test(s[1])&&!/andamento/i.test(s[1])?'Iniciada':'Em andamento';modo='s';return}
   const c=t.match(/^Coment[aá]rios:\s*(.*)$/i);if(c){a.comentario=c[1];modo='c';return}if(modo==='t')a.texto+=' '+t;else if(modo==='c')a.comentario+=' '+t});
  let o=null;(sec.oc||[]).forEach(t=>{const m=t.match(/^Tipo:\s*(.+)$/i);if(m){o={tipo:m[1].trim(),texto:''};r.ocorrencias_l.push(o);return}if(o)o.texto=(o.texto+' '+t).trim()});
  const co=(sec.co||[]);const iF=co.findIndex(t=>/^\[Coment[aá]rios Fiscaliza/i.test(t));const iA=co.findIndex(t=>/^\[Coment[aá]rios/i.test(t)&&!/Fiscaliza/i.test(t));
  const emp=co.slice(iA>=0?iA+1:0,iF>=0?iF:co.length);const fis=iF>=0?co.slice(iF+1):[];if(iF>=0){const fm=co[iF].match(/Fiscaliza[cç][aã]o\s*-\s*([^\]]+)\]/i);r.fiscal=fm?fm[1].trim():null}
  const hm=s=>{const m=String(s||'').match(/(\d{1,2})[:h](\d{2})/);return m?m[1].padStart(2,'0')+':'+m[2]:null};const keep=[];
  emp.forEach((t,i)=>{let m;if((m=t.match(/^Hor[aá]rio:\s*(\d{1,2}[:h]\d{2})\s*(?:às|as|a|-)\s*(\d{1,2}[:h]\d{2})/i))&&/DDS/i.test(emp[i-1]||'')){r.dds_ini=hm(m[1]);r.dds_fim=hm(m[2]);return}
   if((m=t.match(/^In[ií]cio das atividades:\s*(.+)$/i))){r.hora_ini=hm(m[1]);return}if((m=t.match(/^(?:Finaliza[cç][aã]o|Fim|T[eé]rmino) das atividades:\s*(.+)$/i))){r.hora_fim=hm(m[1]);return}if(/^Horas produtivas/i.test(t))return;keep.push(t)});
  r.comentarios_empresa=keep.join('\n').trim()||null;r.comentarios_fiscal=fis.join('\n').trim()||null;
  if(!r.atividades.length)r.avisos.push('nenhuma atividade lida');return r})}
const nomeN=s=>semAc(s).replace(/[^A-Z ]/g,' ').replace(/\s+/g,' ').trim();
function nomeMatch(nome,lista){const n=nomeN(nome);if(!n)return null;let f=lista.find(x=>nomeN(x.nome)===n);if(f)return f;const tk=n.split(' ');
 const cand=lista.filter(x=>{const xn=nomeN(x.nome).split(' ');return xn[0]===tk[0]&&xn[xn.length-1]===tk[tk.length-1]});if(cand.length===1)return cand[0];
 const cand2=lista.filter(x=>{const xn=new Set(nomeN(x.nome).split(' '));return tk.filter(w=>w.length>2&&xn.has(w)).length>=Math.min(3,tk.length)});return cand2.length===1?cand2[0]:null}
function obraMatch(txt){if(!txt)return null;const cod=(txt.match(/^(\d{2,5})\s*-/)||[])[1];const obras=(S.ref.obras||[]).filter(o=>o.nome!=='ESCRITÓRIO');const nm=nomeN(txt.replace(/^\d+\s*-\s*/,''));
 return obras.find(o=>cod&&String(o.codigo||'')===cod)||obras.find(o=>nomeN(o.nome)===nm)||obras.find(o=>nm&&(nomeN(o.nome).includes(nm)||nm.includes(nomeN(o.nome))))||(cod?obras.find(o=>nomeN(o.nome).startsWith(cod)||String(o.centro_custo||'').startsWith(cod)):null)||null}

ACT.rdoImportMC=async()=>{S._rmc=null;openModal(`<h2>Importar RDOs do Mais Controle</h2>
 <p class="small">No Mais Controle, abra cada diário (ou o relatório de diários) e exporte em <b>PDF</b>. Selecione aqui um ou vários PDFs: o portal lê número, data, status, aprovador, condição do tempo, mão de obra (ligando aos funcionários do cadastro), equipamentos, atividades, ocorrências, comentários e fotos. O PDF original fica anexado ao RDO.</p>
 <input type="file" id="rmcArq" accept=".pdf,application/pdf" multiple>
 <div style="display:flex;gap:16px;flex-wrap:wrap;margin-top:6px"><label style="display:flex;gap:6px;align-items:center;margin:0;color:var(--text)"><input type="checkbox" id="rmcFotos" checked style="width:auto;margin:0"> Importar as fotos</label><label style="display:flex;gap:6px;align-items:center;margin:0;color:var(--text)"><input type="checkbox" id="rmcPdf" checked style="width:auto;margin:0"> Anexar o PDF original</label><label style="display:flex;gap:6px;align-items:center;margin:0;color:var(--text)"><input type="checkbox" id="rmcPonto" style="width:auto;margin:0"> Apropriar a mão de obra no ponto (só onde não houver ponto lançado)</label></div>
 <div id="err" class="err"></div><div id="rmcRes" class="small"></div><div class="modal-actions"><button class="btn" data-act="close">Fechar</button><button class="btn primary" data-act="rdoImportMCOk" disabled>Importar</button></div>`,true)};
FIELD.push(async ev=>{const t=ev.target;if(!t)return false;
 if(t.id==='rmcArq'){if(ev.type!=='change')return true;const fs=[...t.files];if(!fs.length)return true;$('#err').textContent='';const res=$('#rmcRes');const fotos=$('#rmcFotos').checked;const out=[];
  const[func,exist]=await Promise.all([S.api.select('funcionarios',{cols:'id,nome,funcao_id,status'}).catch(()=>[]),tfEquipe()]);const users=(TF.eq||[]).filter(x=>x.tipo==='usuario');
  for(const[k,f]of fs.entries()){res.innerHTML=`Lendo ${k+1} de ${fs.length}: ${esc(f.name)}…`;try{const lido=await rdoPdfLer(f,fotos);const rs=rdoMcParse(lido);if(!rs.length){out.push({f,erro:'não parece um RDO do Mais Controle'});continue}
   rs.forEach(r=>{r.f=f;r.fotos=lido.fotos.filter(x=>x.p>=r.p0&&x.p<=r.p1).map(x=>x.blob);const ob=obraMatch(r.obra);r.obra_id=ob?ob.id:'';r.autor=nomeMatch(r.criado_por,users);
    r.mao_obra.forEach(m=>{const fu=nomeMatch(m.nome,func);if(fu){m.funcionario_id=fu.id;m.nome=fu.nome;m.funcao=funcaoNome(fu.funcao_id)||m.funcao}});out.push(r)})}catch(e){out.push({f,erro:e.message})}}
  S._rmcEx=await S.api.select('obra_diarios',{cols:'id,obra_id,data,numero'}).catch(()=>[]);out.forEach(rdoImportJa);out.sort((a,b)=>String(a.data||'').localeCompare(String(b.data||'')));S._rmc=out;rdoImportPrev();return true}
 if(t.dataset&&t.dataset.rmco!==undefined){if(ev.type==='change'){const r=S._rmc[+t.dataset.rmco];r.obra_id=t.value;rdoImportJa(r);rdoImportPrev()}return true}
 if(t.dataset&&t.dataset.rmci!==undefined){if(ev.type==='change'){S._rmc[+t.dataset.rmci].pular=!t.checked;rdoImportPrev()}return true}
 return false});
function rdoImportPrev(){const L=S._rmc||[];const obras=(S.ref.obras||[]).filter(o=>o.nome!=='ESCRITÓRIO');const ok=r=>!r.erro&&r.obra_id&&!r.ja&&!r.pular;const n=L.filter(ok).length;
 $('#rmcRes').innerHTML=`<div class="grid kpis" style="grid-template-columns:repeat(auto-fit,minmax(140px,1fr));margin:10px 0">${kc('RDOs lidos',L.filter(r=>!r.erro).length,L.filter(r=>r.erro).length?L.filter(r=>r.erro).length+' arquivo(s) com erro':'')}${kc('Serão importados',n,'','ok')}${kc('Já existem no portal',L.filter(r=>r.ja).length,'mesmo nº na mesma obra: ignorados')}${kc('Sem obra identificada',L.filter(r=>!r.erro&&!r.obra_id).length,'escolha a obra na lista',L.some(r=>!r.erro&&!r.obra_id)?'warn':'')}</div>
 <div class="tablewrap" style="max-height:48vh;overflow:auto;border:1px solid var(--line);border-radius:8px"><table class="small"><thead><tr><th></th><th>RDO</th><th>Data</th><th>Obra no PDF → obra no portal</th><th>Status</th><th>Mão de obra</th><th class="num">Equip.</th><th class="num">Ativ.</th><th class="num">Fotos</th><th>Observação</th></tr></thead><tbody>
 ${L.map((r,i)=>r.erro?`<tr><td></td><td colspan="9" style="color:var(--bad)">${esc(r.f.name)}: ${esc(r.erro)}</td></tr>`:`<tr style="${ok(r)?'':'opacity:.6'}"><td><input type="checkbox" data-rmci="${i}" ${!r.pular&&!r.ja?'checked':''} ${r.ja?'disabled':''} style="width:auto"></td><td><b>#${r.numero}</b></td><td>${fD(r.data)}</td>
  <td><div class="muted">${esc(r.obra||'—')}</div><select data-rmco="${i}" style="margin:2px 0 0;padding:3px 6px">${'<option value="">Escolha a obra…</option>'+obras.map(o=>`<option value="${o.id}" ${o.id===r.obra_id?'selected':''}>${esc(o.nome)}</option>`).join('')}</select></td>
  <td>${pill(r.status,RDO_ST[r.status])}${r.aprovado_por?`<div class="muted">${esc(r.aprovado_por)}</div>`:''}</td><td>${r.mao_obra.filter(m=>m.funcionario_id).length} de ${r.mao_obra.length} no cadastro${r.efetivo.length?` + ${r.efetivo.reduce((s,e)=>s+e.qtd,0)} terc.`:''}${r.mao_obra.filter(m=>!m.funcionario_id).length?`<div class="muted" title="${esc(r.mao_obra.filter(m=>!m.funcionario_id).map(m=>m.nome).join(', '))}">não achados: ${esc(r.mao_obra.filter(m=>!m.funcionario_id).map(m=>m.nome.split(' ')[0]).join(', '))}</div>`:''}</td>
  <td class="num">${r.equipamentos.length}</td><td class="num">${r.atividades.length}</td><td class="num">${r.fotos.length}</td><td>${r.ja?pill('nº '+r.numero+' já existe nesta obra','')+' ':''}${!r.ja&&r.mesmaData?`<span style="color:var(--warn,#b7791f)">já há o RDO #${r.mesmaData.numero} nesta obra em ${fD(r.data)} (confira se não é o mesmo)</span> `:''}${r.avisos.map(esc).join('; ')}</td></tr>`).join('')}</tbody></table></div>
 <p class="small muted mt">Funcionários não achados no cadastro entram no RDO só com o nome (sem ligação com o ponto). O tempo (sol/nublado/chuva) não vem no texto do PDF: fica a condição praticável/impraticável.</p>`;
 const b=$('[data-act="rdoImportMCOk"]');b.disabled=!n;b.textContent=n?`Importar ${n} RDO(s)`:'Importar'}
ACT.rdoImportMCOk=async()=>{const L=(S._rmc||[]).filter(r=>!r.erro&&r.obra_id&&!r.ja&&!r.pular);if(!L.length)return;const b=$('[data-act="rdoImportMCOk"]');b.disabled=true;const anexar=$('#rmcPdf').checked,apr=$('#rmcPonto').checked;const pdfs={};let n=0,nf=0;const erros=[];
 for(const[k,r]of L.entries()){b.textContent=`Importando ${k+1} de ${L.length}…`;try{
  const fotos=[];for(const[j,bl]of r.fotos.entries()){const path=`obras/rdo/${r.obra_id}/${r.data}_mc${r.numero}_${j+1}.jpg`;try{await S.api.upload(path,new File([bl],`rdo${r.numero}_${j+1}.jpg`,{type:'image/jpeg'}));fotos.push({path,nome:`foto ${j+1}`});nf++}catch(e){}}
  let arq=null;if(anexar){const key=r.f.name+r.f.size;if(!pdfs[key]){const path=`obras/rdo/${r.obra_id}/mc_${Date.now()}_${r.f.name.replace(/[^\w.-]+/g,'_')}`;try{await S.api.upload(path,r.f);pdfs[key]=path}catch(e){}}arq=pdfs[key]||null}
  const row={obra_id:r.obra_id,data:r.data,numero:r.numero,status:r.status,cond_manha:r.cond_manha,cond_tarde:r.cond_tarde,praticavel:r.cond_manha!=='Impraticável'||r.cond_tarde!=='Impraticável',mao_obra:r.mao_obra.map(m=>({funcionario_id:m.funcionario_id||null,nome:m.nome,funcao:m.funcao})),efetivo:r.efetivo,equipamentos:r.equipamentos,atividades:r.atividades,ocorrencias_l:r.ocorrencias_l,
   comentarios_empresa:r.comentarios_empresa,comentarios_fiscal:r.comentarios_fiscal,dds_ini:r.dds_ini||null,dds_fim:r.dds_fim||null,hora_ini:r.hora_ini||null,hora_fim:r.hora_fim||null,fotos,autor_id:r.autor?r.autor.id:null,arquivo_path:arq,
   aprov_fiscal:r.status!=='Em análise'&&(r.aprovado_por||r.fiscal)?{nome:r.aprovado_por||r.fiscal,decisao:r.status==='Reprovado'?'Reprovado':'Aprovado',em:null,importado:true}:null,
   importado:{origem:'Mais Controle',arquivo:r.f.name,criado_por:r.criado_por,aprovado_por:r.aprovado_por,contrato:r.contrato,importado_em:new Date().toISOString(),por:S.user.id}};
  const ins=(await S.api.insert('obra_diarios',[row]))[0];n++;
  if(apr&&row.mao_obra.some(m=>m.funcionario_id)){const pt=await S.api.select('ponto',{eq:{data:r.data}}).catch(()=>null);if(pt){const P=DEF(pdk(r.data));const novos=row.mao_obra.filter(m=>m.funcionario_id&&!pt.some(p=>p.funcionario_id===m.funcionario_id)).map(m=>({funcionario_id:m.funcionario_id,data:r.data,ocorrencia:'TRABALHADO',entrada1:P.entrada1,saida1:P.saida1,entrada2:P.entrada2,saida2:P.saida2,obra_id:r.obra_id,observacao:'Lançado pelo RDO #'+r.numero+' (Mais Controle)'}));if(novos.length){try{await S.api.insert('ponto',novos);await S.api.update('obra_diarios',{id:ins.id},{ponto_aplicado_em:new Date().toISOString()}).catch(()=>null)}catch(e){erros.push(`RDO #${r.numero}: ponto não lançado (${e.message})`)}}}}
 }catch(e){erros.push(`RDO #${r.numero} (${fD(r.data)}): ${/numero|unique|duplicate/i.test(e.message)?'o nº '+r.numero+' já existe nesta obra':/importado|arquivo_path|column/i.test(e.message)?'rode os ajustes 23 e 26 no Supabase':e.message}`)}}
 await evento('Importou RDOs do Mais Controle',n+' RDOs · '+nf+' fotos');$('#rmcRes').innerHTML=`<div class="note mt"><b>${n} RDO(s) importado(s)</b>, com ${nf} foto(s).${erros.length?`<br><span style="color:var(--bad)">${erros.map(esc).join('<br>')}</span>`:''}</div>`;b.textContent='Concluído';$('[data-act="close"]').addEventListener('click',()=>reload(),{once:true})};
ACT.rdoPdfOrig=async()=>{const {r}=D();window.open(await S.api.signedUrl(r.arquivo_path),'_blank')};

function rdoImportJa(r){if(r.erro)return;const ex=S._rmcEx||[];r.ja=r.obra_id?ex.find(x=>x.obra_id===r.obra_id&&+x.numero===+r.numero):null;r.mesmaData=r.obra_id&&r.data?ex.find(x=>x.obra_id===r.obra_id&&String(x.data).slice(0,10)===r.data&&+x.numero!==+r.numero):null;if(r.ja)r.pular=false}
// ---------------------------------------------------------------- IMPORTAR ORÇAMENTOS DO MAIS CONTROLE EM LOTE ("Exportar Sintético" em Excel)
// Cada arquivo vira um orçamento: etapas e itens (código, banco, descrição, und, quantidade, custo unitário e BDI),
// com obra, cliente, código e situação (Venda = fechado). O total do arquivo é conferido com o total calculado.
function orcMcMeta(rows,h,fname){const lim=Math.max(h,0);const cel=(i,c)=>{const v=(rows[i]||[])[c];return v==null?'':String(v).trim()};
 // rótulo e valor: "Obra: X" na mesma célula, rótulo com ":" e valor à direita, ou rótulo em cima e valor embaixo (layout do Mais Controle)
 const pega=re=>{for(let i=0;i<lim;i++){const r=rows[i]||[];for(let c=0;c<r.length;c++){const raw=cel(i,c);if(!raw)continue;const m=impN(raw).match(re);if(!m)continue;
   const dep=raw.match(/:\s*(.+)$/);if(dep&&dep[1].trim())return dep[1].trim();
   if(/:\s*$/.test(raw)){for(let k=c+1;k<Math.min(r.length,c+4);k++)if(cel(i,k))return cel(i,k);return ''}
   for(const k of [c,c+1,c+2]){const v=cel(i+1,k);if(v)return v}}}return ''};
 const m={obra:pega(/^OBRA$/),cliente:pega(/^(CLIENTE|CONTRATANTE|PROPRIETARIO)$/),orc:pega(/^ORCAMENTO( N| NO| NUMERO| COD[A-Z]*)?$/),titulo:pega(/^(DESCRICAO|OBJETO|TITULO)$/),base:pega(/^(BANCOS?|DATA BASE|REFERENCIA)$/),
  status:pega(/^STATUS DA OBRA$/),tipo:pega(/^TIPO DE OBRA$/),endereco:pega(/^ENDERECO$/),bdi:numPl(pega(/^BDI( %)?$/)),custo_total:numPl(pega(/^CUSTO TOTAL$/)),preco_total:numPl(pega(/^(PRECO TOTAL|VALOR TOTAL|TOTAL GERAL)$/))};
 if(m.bdi==null){for(let i=0;i<lim&&m.bdi==null;i++)for(const x of rows[i]||[]){const b=semAc(String(x||'')).match(/^BDI[^0-9]{0,15}([\d]+[.,]?\d*)\s*%/);if(b){m.bdi=numPl(b[1]);break}}}
 let ger='';for(let i=0;i<lim;i++)for(let c=0;c<(rows[i]||[]).length;c++){const g=cel(i,c).match(/(\d{2})\/(\d{2})\/(\d{4})/);if(g&&!ger)ger=g[3]}
 const cod=(m.orc.match(/\d+(\/\d{2,4})?/)||m.obra.match(/^(\d{1,6})\s*-/)||String(fname).match(/(\d+\/\d{4}|\d{2,6})/)||[]);const c0=cod[1]&&!cod[0].includes('/')?cod[1]:cod[0];
 m.codigo=c0?(String(c0).includes('/')?c0:c0+'/'+(ger||T0.getFullYear())):'';
 if(!m.obra)m.obra=String(fname).replace(/\.(xlsx|csv|txt)$/i,'').replace(/^(or[cç]amento)?[\s_-]*(sint[eé]tico)?[\s_-]*/i,'').replace(/_+/g,' ').trim();
 return m}
function orcMcTotal(rows,h,ix,M){if(M&&M.preco_total)return M.preco_total;let tot=null;for(let i=h+1;i<rows.length;i++){const r=rows[i]||[];const t=semAc(r.map(x=>String(x==null?'':x)).join(' '));if(/TOTAL\s*(GERAL|DO ORCAMENTO|COM BDI|C\/\s*BDI)|^\s*TOTAL\s*$|VALOR TOTAL/.test(t)&&!/SEM BDI|S\/\s*BDI/.test(t)){const ns=r.map(numPl).filter(n=>n!=null&&n>0);if(ns.length)tot=Math.max(...ns)}}return tot}
