async function crTarefasObra(obra){const orcs=((await obBase()).orcs||[]).filter(o=>o.obra_id===obra&&!['Cancelada','Perdida'].includes(o.status_proposta));if(!orcs.length)return null;
 const ts=await S.api.select('cron_tarefas',{in:{orcamento_id:orcs.map(o=>o.id)}}).catch(()=>null);if(!ts||!ts.length)return null;
 const com=orcs.filter(o=>ts.some(t=>t.orcamento_id===o.id)).sort((a,b)=>(b.status_proposta==='Venda')-(a.status_proposta==='Venda')||String(b.criado_em).localeCompare(String(a.criado_em)))[0];
 const tk=ts.filter(t=>t.orcamento_id===com.id);const G=crCalc(tk,crCfg(com));return {o:com,tasks:tk,G,folhas:G.ord.filter(G.leaf).map(id=>({id,wbs:G.M[id].wbs,nome:G.M[id].t.nome,av:+G.M[id].t.avanco||0,ini:G.M[id].ini,fim:G.M[id].fim}))}}

