INI_LOAD.push(async o=>{if(!perm('engenharia','ver'))return;if(S._crRot!==dk(T0)){S._crRot=dk(T0);S.api.rpc('cron_rotina',{}).catch(()=>{})}o.crSt=await S.api.rpc('cron_status',{}).catch(()=>null)});
INI_EXT.push((o,add)=>{(o.crSt||[]).filter(s=>s.atrasadas>0).forEach(s=>{const ob=obraObj(s.obra_id);if(!(S.perfil.master||ob.responsavel_id===S.user.id||perm('engenharia','aprovar')))return;
 add('eng',s.realizado+10<s.previsto?'bad':'warn',`Cronograma de ${ob.nome||'obra'}: ${s.atrasadas} tarefa(s) fora do prazo · previsto ${N(+s.previsto||0,1)}% × realizado ${N(+s.realizado||0,1)}%`,'orcdet',s.orcamento_id,'crAbrir')})});

